    })));
    const {
        isPanelOpen, setIsPanelOpen,
        setPanelTab,
        isHomeFullyHidden, setIsHomeFullyHidden,
    } = useAppViewStore(useShallow(state => ({
        isPanelOpen: state.isPanelOpen,
