            {isMobileShellActive && (
                <MobileAppContainer
                    localSongs={localSongs}
                    localPlaylists={localPlaylists}
                    localLibraryCatalog={localLibraryCatalog}
                    currentSong={playerDisplayCurrentSong}
                    coverUrl={displayCoverUrl || playerDisplayCurrentSong?.album?.coverUrl || null}
                    playerState={displayPlayerState}
                    currentTime={currentTime}
                    lyricCurrentTime={lyricCurrentTime}
                    duration={displayDuration}
                    lyrics={displayLyrics}
                    currentLineIndex={currentLineIndex}
                    isLyricsLoading={isLyricsLoading}
                    isLiked={commandPaletteContext.playback.isSongLiked}
                    loopMode={effectiveLoopMode}
                    replayGainMode={usePlaybackStore.getState().replayGainMode}
                    onChangeReplayGainMode={handleChangeReplayGainMode}
                    theme={theme}
                    onToggleDaylight={toggleDaylightMode}
                    lyricTimelineOffsetMs={lyricTimelineOffsetMs}
                    onLyricTimelineOffsetChange={handleLyricTimelineOffsetChange}
                    onChangeLyricsSource={handleChangeLyricsSource}
                    onUpdateLocalLyrics={handleUpdateLocalLyrics}
                    onOpenLyricMatch={openLyricMatch}
                    onCloseLyricMatch={closeLyricMatch}
                    isLyricMatchOpen={isLyricMatchOpen}
                    onTogglePureMusic={handleToggleCurrentSongPureMusicMark}
                    onRefreshLocalSongs={onRefreshLocalSongs}
                    onPlayLocalSong={onPlayLocalSong}
                    onAddLocalSongToQueue={handleLocalQueueAdd}
                    playQueue={playerDisplayQueue}
                    onPlayQueueSong={playSong}
                    onRemoveQueueSong={removeQueueSong}
                    onSaveQueueAsPlaylist={saveCurrentQueueAsPlaylist}
                    onSeek={seekMainAudio}
                    onLyricLineSeek={handleMonetLyricLineSeek}
                    onTogglePlay={togglePlay}
                    onPrevTrack={handlePrevTrack}
                    onNextTrack={() => { void handleNextTrack(); }}
                    onToggleLoop={toggleLoop}
                    onToggleLike={handleLike}
                    onShuffleQueue={shuffleQueue}
                    isCommandPaletteOpen={commandPalette.isOpen}
                    onCloseCommandPalette={commandPalette.close}
                    onVisualizerVisibilityChange={setIsMobileVisualizerActive}
                    isLatticeOpen={currentView === 'lattice'}
                    onOpenLattice={navigateToLattice}
                    onCloseLattice={navigateBackFromLattice}
                    onPlayOnlineSong={(song, queue) => { void playSong(song, queue); }}
                    onAddOnlineSongToQueue={addOnlineSongToQueue}
                    onPlayNavidromeSong={(song, queue) => { void onPlayNavidromeSong(song, queue); }}
                    onAddNavidromeSongsToQueue={addNavidromeSongsToQueue}
                    onOpenFullSearchWorkspace={() => navigateToSearch({ query: '', sourceTab: 'online' })}
                    onCloseSearch={closeSearchView}
                    isSearchOpen={isSearchOpen}
                    onAutoMatchLyrics={() => { void handleAutoMatchBestLyricForCurrentSong(); }}
                />
            )}

            <ThemeQuickEditorHost onSaveAiTheme={saveEditedAiDualTheme} onSaveCustomTheme={saveCustomDualTheme} />

            {/* Mounted here rather than inside the panel that used to own it: the picker answers a
                question about the current song, and a shortcut has to reach it with the panel shut. */}
            <AddToPlaylistHost
                isDaylight={isDaylight}
                onAddSongsToOnlinePlaylist={addPickedSongsToOnlinePlaylist}
                onCreateOnlinePlaylistWithSongs={createOnlinePlaylistWithSongs}
                onAddSongsToNavidromePlaylist={addPickedSongsToNavidromePlaylist}
                onCreateNavidromePlaylistWithSongs={createNavidromePlaylistWithSongs}
                isFoliaSongLiked={isFoliaSongLiked}
            />

            {/* 速记簿：左缘的把手与滑出的抽屉，非模态，三个视图里都在；播放页隐藏 UI 时把手跟着藏起来。 */}
            <ScratchpadHost
                isDaylight={isDaylight}
                playback={scratchpadPlayback}
                queue={scratchpadQueue}
                isHandleHidden={currentView === 'player' && isPlayerChromeHidden}
            />

            {/* 胶囊槽位「记下这个时刻」弹出的小框：全局一份，钉在点下的那个按钮上方。 */}
            <SongNotePinHost />

            <CommandPalette
                activeIndex={commandPalette.activeIndex}
                activePreview={commandPalette.activePreview}
                activeCommand={commandPalette.activeCommand}
                availableCommands={commandPalette.availableCommands}
                context={commandPaletteContext}
                isDaylight={isDaylight}
                isComposing={commandPalette.isComposing}
                isExecuting={commandPalette.isExecuting}
                isOpen={commandPalette.isOpen}
                matches={commandPalette.matches}
                pinnedCommands={commandPalette.pinnedCommands}
                query={commandPalette.query}
                theme={theme}
                onActiveCommandChange={commandPalette.setActiveCommand}
                onActiveIndexChange={commandPalette.setActiveIndex}
                onClose={commandPalette.close}
                onCompositionEnd={(value) => {
                    commandPalette.setIsComposing(false);
                    commandPalette.commitQuery(value);
                }}
                onCompositionStart={() => commandPalette.setIsComposing(true)}
                onExecuteActive={commandPalette.executeActive}
                onExecuteMatch={commandPalette.executeMatch}
                onExecutePinnedCommand={commandPalette.executePinnedCommand}
                onQueryChange={commandPalette.setQuery}
                onQueryCommit={commandPalette.commitQuery}
            />

            <AppDialogs model={appDialogsModel} />
            <AudioEqualizerDialog isDaylight={isDaylight} />
            {/* 登录窗口挂在最外层：每个资料库界面（网格、Bravais、文本）都用 openLoginWindow 打开同一个窗口。 */}
            <LoginHost account={accountController} />
            {signOutDialog}
            <ReleaseNotesDialog
                isOpen={startupExperience.isReleaseNotesOpen}
                isDaylight={isDaylight}
                onClose={startupExperience.closeReleaseNotes}
            />
            <UserGuideModal theme={theme} />
            <PlaybackEntryViewPrompt theme={theme} />
            <LocalFolderAccessPrompt theme={theme} />
            {/* With 自动 AI 分词 on, segments a song that has no saved split by itself (issue #960). */}
            <AutoLyricSegmentationHost visualizerMode={visualizerMode} isLyricsLoading={isLyricsLoading} save={lyricSegmentationActions.save} />
            <TrackEndCountdownHost enabled={stageTrackPillOnScreen && nextUpTrack !== null} duration={displayDuration} />
        </AppShell>
    );
}

