import { useCallback, useEffect, useMemo, useRef } from 'react';
import type { MutableRefObject, RefObject } from 'react';
import { PlayerState } from '../../../../types';
import type { ReplayGainInfo, ReplayGainMode, SongResult, StatusMessage } from '../../../../types';
import type { LocalSong } from '../../../../types';
import { isLocalPlaybackSong, resolveNavidromePlaybackCarrier } from '../../../../utils/appPlaybackGuards';
import { calculateReplayGain } from '../../../../utils/replayGain';
import { applyAudioEqualizerSettings, planAudioEqualizerApply } from '../../../../services/audioEqualizerGraph';
import { type AudioEffectChain } from '../../../../services/audioEffects/effectChain';
import { buildPlaybackGraph } from '../../../../services/playbackGraph';
import { cachePlayedTrackAssets } from '../../../../services/playedTrackCache';
import { markProgrammaticPause, registerPlaybackFadeGraph } from '../../../../services/playbackFade';
import {
    bindAudioElementToNativeExoPlayer,
    isAndroidSafStreamUrl,
    loadAndroidNativeTrack,
    setAndroidNativeExoPlayerActive,
    shouldRouteToAndroidNativeExoPlayer,
} from '../../../../services/android/foliaAndroidBridge';
import { getSongAlbumLabel, getSongArtistLabel } from '../../../../services/onlineMusic/songMetadata';
import { shouldBypassWebAudioDspGraph } from '../../../../utils/audioEqualizer';
import { registerRoomSlot } from '../../../../services/sceneSound/roomStage';
import { applySavedAudioOutputToContext } from '../../../../services/audioOutputSink';
import { rampGain, type AutomixDeckChain } from '../../../../services/automix/crossfadeGraph';
import { onTrackProfile } from '../../../../services/automix/profileService';
import { onPlayWrapped } from '../../../../services/volumeBalance/balanceMeter';
import { createBalancePlay } from '../../../../services/volumeBalance/balancePlay';
import { onBalanceRecord } from '../../../../services/volumeBalance/balanceRecords';
import { setStatusMessage as setStatusMsg } from '../../../../stores/useStatusMessageStore';
import { useAudioSettingsStore } from '../../../../stores/useAudioSettingsStore';
import { setPlayerState, setReplayGainAppliedDb, setReplayGainEstimated } from '../../../../stores/usePlaybackStore';
import { useTranslation } from 'react-i18next';
import { usePlaybackStore } from '../../../../stores/usePlaybackStore';
import { resolveHeardAudioEqualizerSettings } from '../../../../utils/audioEqualizerModCurve';

// src/components/app/playback/bridges/usePlaybackAudioBridge.ts

type UsePlaybackAudioBridgeParams = {
    automixEnabled?: boolean;
    stemSeparationEnabled?: boolean;

    audioRef: RefObject<HTMLAudioElement | null>;
    localSongs: LocalSong[];
    isLyricsLoading: boolean;
    shouldAutoPlayRef: MutableRefObject<boolean>;
    audioContextRef: MutableRefObject<AudioContext | null>;
    analyserRef: MutableRefObject<AnalyserNode | null>;
    gainNodeRef: MutableRefObject<GainNode | null>;
    /** Wires both automix decks into the shared mix point. Returns false if a deck is missing. */
    connectDecks: (context: AudioContext, output: AudioNode) => boolean;
    /** The deck the app is currently listening through, for per-track loudness compensation. */
    getActiveChain: () => AutomixDeckChain | null;
    /** Set when a pause interrupted an armed transition; suppresses exactly one autoplay. */
    suppressAutoplayRef: MutableRefObject<boolean>;
    /** True while automix has the next track loaded but its blend is not due to start yet. */
    isAutoplayHeld: boolean;
    syncOutputGain: (targetVolume: number, smoothing?: number) => void;
    getTargetPlaybackVolume: () => number;
    getCoverUrl: () => string | null;
    /** Whether an automix blend can be heard now; a mod's equalizer change waits until it cannot. */
    isTransitionAudible?: () => boolean;
};

/** How often a mod's equalizer change held back for a blend checks whether the blend has ended. */
const DEFERRED_EQUALIZER_POLL_MS = 250;
/** How often 智能平衡 looks again at a playing song: its deck's meter, a blend that ended. */
const BALANCE_POLL_MS = 500;

// Bridges audio element setup, autoplay, replay gain, and media caching.
export function usePlaybackAudioBridge({
    automixEnabled = false,
    stemSeparationEnabled = false,
    audioRef,
    localSongs,
    isLyricsLoading,
    shouldAutoPlayRef,
    audioContextRef,
    analyserRef,
    gainNodeRef,
    connectDecks,
    getActiveChain,
    suppressAutoplayRef,
    isAutoplayHeld,
    syncOutputGain,
    getTargetPlaybackVolume,
    getCoverUrl,
    isTransitionAudible,
}: UsePlaybackAudioBridgeParams) {
    // Read here rather than passed in: all store fields or i18n.
    const { t } = useTranslation();
    const audioSrc = usePlaybackStore(state => state.audioSrc);
    const currentSong = usePlaybackStore(state => state.currentSong);
    const replayGainMode = usePlaybackStore(state => state.replayGainMode);
    const enableMediaCache = useAudioSettingsStore(state => state.enableMediaCache);

    const previousAudioSrcRef = useRef<string | null>(null);
    const replayGainLogSignatureRef = useRef<string | null>(null);
    const balancePlayRef = useRef<ReturnType<typeof createBalancePlay> | null>(null);
    balancePlayRef.current ??= createBalancePlay();
    const equalizerNodesRef = useRef<BiquadFilterNode[]>([]);
    const effectChainRef = useRef<AudioEffectChain | null>(null);
    const audioEqualizerSettings = useAudioSettingsStore(state => state.audioEqualizerSettings);

    // The flat, no-automix case may hand playback to Android's native ExoPlayer (opt-in).
    const shouldBypassDsp = shouldBypassWebAudioDspGraph({ equalizerSettings: audioEqualizerSettings, automixEnabled, stemSeparationEnabled });
    const forceNativeExoOverride = typeof window !== 'undefined'
        && Boolean((window as Window & { __FOLIA_FORCE_NATIVE_EXOPLAYER__?: boolean }).__FOLIA_FORCE_NATIVE_EXOPLAYER__);
    const useNativeExoPlayer = forceNativeExoOverride && shouldRouteToAndroidNativeExoPlayer({
        audioSrc,
        automixEnabled,
        stemSeparationEnabled,
        equalizerEnabled: !shouldBypassDsp,
    });
    const lastLoadedExoSrcRef = useRef<string | null>(null);

    useEffect(() => {
        setAndroidNativeExoPlayerActive(useNativeExoPlayer);
        bindAudioElementToNativeExoPlayer(audioRef.current, useNativeExoPlayer);
        if (!useNativeExoPlayer) {
            lastLoadedExoSrcRef.current = null;
        }
        return () => {
            if (!useNativeExoPlayer && audioRef.current) {
                bindAudioElementToNativeExoPlayer(audioRef.current, false);
            }
        };
    }, [audioRef, useNativeExoPlayer]);
    // What is heard: the listener's own settings with a mod's curve over the gains (Folium 1.7). Worked out
    // here rather than in a selector, which would hand useSyncExternalStore a new object on every read.
    const modCurve = useAudioSettingsStore(state => state.audioEqualizerModCurve);
    const modCurveSuspended = useAudioSettingsStore(state => state.audioEqualizerModCurveSuspended);
    const equalizerOrigin = useAudioSettingsStore(state => state.audioEqualizerChangeOrigin);
    const heardEqualizerSettings = useMemo(
        () => resolveHeardAudioEqualizerSettings(audioEqualizerSettings, modCurve, modCurveSuspended),
        [audioEqualizerSettings, modCurve, modCurveSuspended],
    );
    const heardEqualizerSettingsRef = useRef(heardEqualizerSettings);
    const isTransitionAudibleRef = useRef(isTransitionAudible);
    // Read only in the equalizer effect and its timer; written in an effect, not while rendering.
    useEffect(() => {
        isTransitionAudibleRef.current = isTransitionAudible;
    }, [isTransitionAudible]);

    // Recalculates source-specific gain after the audio graph or playback settings become ready.
    const applyReplayGain = useCallback(() => {
        if (!currentSong || !gainNodeRef.current || !audioContextRef.current) return;

        let replayGainInfo: ReplayGainInfo | undefined;
        const localSongId = (currentSong as SongResult & { localRef?: { songId: string } }).localRef?.songId;
        const localData = localSongId ? localSongs.find(song => song.id === localSongId) : undefined;
        if ((currentSong as SongResult & { isLocal?: boolean }).isLocal && localData) {
            replayGainInfo = {
                trackGain: typeof localData.replayGainTrackGain === 'number'
                    ? localData.replayGainTrackGain
                    : localData.replayGain,
                trackPeak: localData.replayGainTrackPeak,
                albumGain: localData.replayGainAlbumGain,
                albumPeak: localData.replayGainAlbumPeak,
            };
        }

        const navidromeSong = resolveNavidromePlaybackCarrier(currentSong);
        const navidromeReplayGain = navidromeSong?.navidromeData.replayGain;
        if (navidromeReplayGain) {
            replayGainInfo = navidromeReplayGain;
        }

        if (currentSong.sourceRef?.kind === 'online') {
            replayGainInfo = currentSong.replayGain;
        }

        try {
            // Onto the deck rather than the shared output: loudness compensation is a per-track
            // value, so during a blend the two decks legitimately need different ones.
            const activeChain = getActiveChain();
            // 智能平衡 decides per play, from what it knows of the song (services/volumeBalance).
            if (replayGainMode === 'auto') {
                const applied = balancePlayRef.current!.apply({
                    song: currentSong,
                    info: replayGainInfo,
                    chain: activeChain,
                    context: audioContextRef.current,
                    transitionAudible: isTransitionAudibleRef.current?.() ?? false,
                });
                // With no deck to take it nothing is applied, and the last song's figure must not stay shown.
                setReplayGainAppliedDb(applied?.gainDb ?? 0);
                setReplayGainEstimated(applied?.estimated ?? false);
                return;
            }
            balancePlayRef.current!.reset();
            setReplayGainEstimated(false);
            const calculation = calculateReplayGain(replayGainInfo, replayGainMode);
            if (activeChain) {
                rampGain(audioContextRef.current, activeChain.replayGain, calculation.linearGain, 0.1);
                setReplayGainAppliedDb(calculation.effectiveGainDb);
            }

            const replayGainLogSignature = JSON.stringify({
                songId: currentSong.id,
                mode: replayGainMode,
                raw: calculation.gainDb,
                effective: calculation.effectiveGainDb,
                peak: calculation.peak ?? null,
            });

            if (replayGainLogSignatureRef.current !== replayGainLogSignature) {
                replayGainLogSignatureRef.current = replayGainLogSignature;
                console.log(`[AudioContext] ReplayGain mode=${replayGainMode} gain=${calculation.effectiveGainDb}dB (raw=${calculation.gainDb}dB, peak=${calculation.peak ?? 'n/a'}, linear=${calculation.linearGain.toFixed(2)})`);
            }
        } catch (error) {
            console.warn('[AudioContext] Failed to apply ReplayGain', error);
        }
    }, [audioContextRef, currentSong, gainNodeRef, getActiveChain, localSongs, replayGainMode]);

    const setupAudioAnalyzer = useCallback(() => {
        // The context is the sentinel, not the source node: a deck that failed to connect must
        // not let this run twice, because createMediaElementSource throws on a second call.
        if (!audioRef.current || audioContextRef.current) return;
        try {
            try {
                const nav = navigator as Navigator & { audioSession?: { type: string } };
                if (nav.audioSession) nav.audioSession.type = 'playback';
            } catch { /* audioSession unsupported */ }
            const AudioContextClass = window.AudioContext || (window as Window & typeof globalThis & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
            const ctx = new AudioContextClass();
            audioContextRef.current = ctx;
            void applySavedAudioOutputToContext(ctx, useAudioSettingsStore.getState().audioOutputDeviceId);

            const analyser = ctx.createAnalyser();
            analyser.fftSize = 2048;
            analyser.smoothingTimeConstant = 0.6;
            analyserRef.current = analyser;

            const { gainNode, fadeNode, effectChain, decksConnected } = buildPlaybackGraph({
                context: ctx,
                analyser,
                connectDecks,
                equalizerNodesRef,
                settings: heardEqualizerSettings,
            });
            gainNodeRef.current = gainNode;
            // Hands the transport its own fade node; until this runs (or if setup fails) pause and
            // resume see no graph and fall back to plain element pause/play.
            registerPlaybackFadeGraph({ context: ctx, gain: fadeNode });
            // Where a scene's room goes when one is shown with its sound on; nothing is wired until then.
            registerRoomSlot({ context: ctx, from: fadeNode, to: gainNode });
            effectChainRef.current = effectChain;
            if (!decksConnected) {
                console.warn('[AudioContext] Deck setup incomplete, automix will stay idle');
            }
            applyReplayGain();
            syncOutputGain(getTargetPlaybackVolume(), 0);
        } catch (error) {
            console.error('Audio Context Setup Failed:', error);
        }
    }, [analyserRef, applyReplayGain, audioContextRef, audioRef, connectDecks, gainNodeRef, getTargetPlaybackVolume, heardEqualizerSettings, syncOutputGain]);

    /**
     * Writes a fully-played track's audio and cover into the media cache.
     *
     * Takes the song and its source explicitly rather than reading `currentSong`/`audioSrc`, because
     * the automix settle path caches the track that just faded OUT - and by then the app's own state
     * already names the track that arrived. `coverUrl` is passed for the currently-displayed track
     * (which may carry a user override); left undefined - the automix path - the cover is taken from
     * the song's own metadata instead.
     *
     * The writes themselves live in `cachePlayedTrackAssets`, which is where the audio and cover
     * conditions are kept apart from each other; this only adds the setting gate, which does not
     * belong in a service.
     */
    const cacheSongAssetsFor = useCallback(async (
        song: SongResult | null,
        src: string | null,
        coverUrl?: string | null,
    ) => {
        if (!enableMediaCache) return;

        await cachePlayedTrackAssets(song, src, coverUrl);
    }, [enableMediaCache]);

    const cacheSongAssets = useCallback(
        () => cacheSongAssetsFor(currentSong, audioSrc, getCoverUrl()),
        [audioSrc, cacheSongAssetsFor, currentSong, getCoverUrl],
    );

    useEffect(() => {
        if (audioRef.current) {
            syncOutputGain(getTargetPlaybackVolume(), 0.015);
        }
    }, [audioRef, getTargetPlaybackVolume, syncOutputGain]);

    useEffect(() => {
        localStorage.setItem('local_replaygain_mode', replayGainMode);
    }, [replayGainMode]);

    useEffect(() => {
        applyReplayGain();
    }, [applyReplayGain]);

    // 智能平衡 looks again when a reading lands - a profile, the song's own record, the deck's meter once it
    // has heard enough - and when a blend ends; the rules decide whether a playing song may still move. A loop
    // come round is a new play, set at once rather than at the next poll.
    useEffect(() => {
        if (replayGainMode !== 'auto') return undefined;
        const offProfile = onTrackProfile(() => applyReplayGain());
        const offRecord = onBalanceRecord(() => applyReplayGain());
        const offWrap = onPlayWrapped(() => applyReplayGain());
        const timer = setInterval(() => applyReplayGain(), BALANCE_POLL_MS);
        return () => {
            offProfile();
            offRecord();
            offWrap();
            clearInterval(timer);
        };
    }, [applyReplayGain, replayGainMode]);

    /*
     * Writes what is heard into the graph. A mod's change waits while an automix blend can be heard and is
     * then applied as it stands by then; any later change re-runs this, which drops the wait and applies at
     * once by its own origin (planAudioEqualizerApply).
     */
    useEffect(() => {
        heardEqualizerSettingsRef.current = heardEqualizerSettings;
        const context = audioContextRef.current;
        if (!context || equalizerNodesRef.current.length === 0) {
            return;
        }
        const plan = planAudioEqualizerApply({
            origin: equalizerOrigin,
            transitionAudible: isTransitionAudibleRef.current?.() ?? false,
        });
        const apply = (settings: typeof heardEqualizerSettings) => {
            applyAudioEqualizerSettings(context, equalizerNodesRef.current, settings, plan.timeConstant);
            effectChainRef.current?.apply(settings.effects, settings.enabled);
        };
        if (!plan.defer) {
            apply(heardEqualizerSettings);
            return;
        }
        const timer = setInterval(() => {
            if (isTransitionAudibleRef.current?.()) {
                return;
            }
            clearInterval(timer);
            apply(heardEqualizerSettingsRef.current);
        }, DEFERRED_EQUALIZER_POLL_MS);
        return () => clearInterval(timer);
    }, [audioContextRef, heardEqualizerSettings, equalizerOrigin]);

    useEffect(() => () => {
        effectChainRef.current?.dispose();
        effectChainRef.current = null;
    }, []);

    useEffect(() => {
        const audioElement = audioRef.current;
        if (!audioElement) {
            previousAudioSrcRef.current = audioSrc;
            return;
        }

        if (audioSrc && previousAudioSrcRef.current && previousAudioSrcRef.current !== audioSrc) {
            if (!audioElement.paused && !audioElement.ended) {
                // Programmatic pause on source switch: App.tsx's onPause must not read it as a user pause.
                markProgrammaticPause(audioElement);
                audioElement.pause();
            }
            audioElement.load();
        }

        previousAudioSrcRef.current = audioSrc;
    }, [audioRef, audioSrc]);

    useEffect(() => {
        if (audioSrc && audioRef.current) {
            // `audioRef` and `audioSrc` describe the same track almost always - but not while a
            // blend is being armed. Automix repoints the ref at the incoming deck the instant it
            // arms, and `audioSrc` keeps naming the OUTGOING track until playSong has resolved the
            // next URL, which takes an await or two. Playing in that window starts whatever the
            // incoming deck still had loaded from an earlier song AND spends the autoplay intent
            // on it, so when the real source lands there is nothing left to press play with: the
            // deck sits fully buffered at currentTime 0 in silence.
            //
            // The deck's own src attribute is written from `audioSrc`, so an exact match is the
            // whole test. Bail WITHOUT spending the intent - this effect runs again on the commit
            // that gives the deck its real source, and that run is the one meant to start it.
            if (useNativeExoPlayer) {
                bindAudioElementToNativeExoPlayer(audioRef.current, true);
                const autoPlayWanted = Boolean(shouldAutoPlayRef.current && !isAutoplayHeld && !suppressAutoplayRef.current);
                if (lastLoadedExoSrcRef.current !== audioSrc) {
                    lastLoadedExoSrcRef.current = audioSrc;
                    if (suppressAutoplayRef.current) {
                        suppressAutoplayRef.current = false;
                        shouldAutoPlayRef.current = false;
                        setPlayerState(PlayerState.PAUSED);
                    } else if (shouldAutoPlayRef.current) {
                        shouldAutoPlayRef.current = false;
                        setPlayerState(PlayerState.PLAYING);
                    }
                    void loadAndroidNativeTrack({
                        url: audioSrc,
                        trackId: currentSong ? String(currentSong.id) : '',
                        title: currentSong?.name || 'Folia',
                        artist: currentSong ? (getSongArtistLabel(currentSong) || '') : '',
                        album: currentSong ? (getSongAlbumLabel(currentSong) || '') : '',
                        artworkUrl: getCoverUrl(),
                        autoPlay: autoPlayWanted,
                        startPositionMs: 0,
                        volume: getTargetPlaybackVolume(),
                        playbackSpeed: 1.0,
                    });
                } else if (autoPlayWanted) {
                    shouldAutoPlayRef.current = false;
                    setPlayerState(PlayerState.PLAYING);
                    void audioRef.current.play();
                }
                return;
            }
            if (audioRef.current.getAttribute('src') !== audioSrc) return;

            // The deck has already failed on this exact source and something else - the transcode
            // fallback - is off resolving it. play() on an element in error state cannot start
            // anything; it rejects with NotSupportedError. Pressing it here only spends the intent,
            // so when the recovered source lands there is nothing left to start the deck with.
            // Bail WITHOUT spending it, the same way the autoplay hold below does: replacing the
            // source runs this effect again, and that run is the one meant to start it.
            if (audioRef.current.error) return;

            // Local sources already have their playable URL and local lyrics before audioSrc commits;
            // do not delay local playback while optional online lyric/cover matching runs in the background.
            const isLocalSourceReady = Boolean(
                isLocalPlaybackSong(currentSong)
                || audioSrc.startsWith('blob:')
                || isAndroidSafStreamUrl(audioSrc)
            );
            if (shouldAutoPlayRef.current && (!isLyricsLoading || isLocalSourceReady)) {
                // The deck has its source and is buffering, but its blend is not due yet. Bail
                // WITHOUT spending the intent - this effect runs again when the hold lifts, and
                // that run is the one meant to start it.
                //
                // This is what keeps the load out of the blend. Pressing play here instead starts
                // the fade wherever loading happened to finish, which took the same second or two
                // off every transition and capped an eight second plan at three.
                if (isAutoplayHeld) {
                    // The outgoing deck is still sounding. playSong dropped the state to IDLE on
                    // its way past and nothing else puts it back until this deck starts, so left
                    // alone the transport reads "stopped" for the whole lead - and the play button
                    // it offers would start this deck early and take the blend with it.
                    setPlayerState(PlayerState.PLAYING);
                    return;
                }

                shouldAutoPlayRef.current = false;

                // Automix starts the next track seconds early, so a pause can land after the
                // advance is already in flight and too late to recall. Honour the pause instead:
                // without this the listener presses pause and the next song starts anyway.
                if (suppressAutoplayRef.current) {
                    suppressAutoplayRef.current = false;
                    setPlayerState(PlayerState.PAUSED);
                    return;
                }

                syncOutputGain(getTargetPlaybackVolume(), 0);
                const playPromise = audioRef.current.play();
                if (playPromise !== undefined) {
                    playPromise
                        .then(() => {
                            setPlayerState(PlayerState.PLAYING);
                            setupAudioAnalyzer();
                        })
                        .catch(error => {
                            if (audioRef.current && !audioRef.current.paused && !audioRef.current.ended) {
                                setPlayerState(PlayerState.PLAYING);
                                return;
                            }

                            // A load() landing between play() and its promise aborts the play.
                            // That happens whenever the source changes again while a track is
                            // still starting - skipping during an automix transition is the
                            // reliable way to see it - and the autoplay flag was spent before
                            // play() was ever called, so nothing would press play again and the
                            // app sits silent. Put the intent back for the next run.
                            if (error.name === 'AbortError') {
                                shouldAutoPlayRef.current = true;
                                return;
                            }

                            if (error.name === 'NotAllowedError') {
                                setStatusMsg({ type: 'info', text: t('status.clickToPlay') });
                                setPlayerState(PlayerState.PAUSED);
                            }
                        });
                }
            }
        }
    }, [audioRef, audioSrc, currentSong, getCoverUrl, getTargetPlaybackVolume, isAutoplayHeld, isLyricsLoading, useNativeExoPlayer, setPlayerState, setStatusMsg, setupAudioAnalyzer, shouldAutoPlayRef, suppressAutoplayRef, syncOutputGain, t]);

    // Tells this bridge that the active deck ALREADY holds `src` and is sounding it, so the next time
    // `audioSrc` settles on that value the reload effect above treats it as a no-op instead of calling
    // load(). Used when a transition is cancelled back onto the deck still playing the outgoing track:
    // that deck has the song loaded and playing, and reloading it would run the whole song-change
    // shape - a fresh load, a visible hitch - for a track that never actually left.
    const adoptActiveDeckSource = useCallback((src: string) => {
        previousAudioSrcRef.current = src;
    }, []);

    return {
        setupAudioAnalyzer,
        cacheSongAssets,
        cacheSongAssetsFor,
        adoptActiveDeckSource,
    };
}

import { useCallback, useEffect, useRef } from 'react';
import type { MutableRefObject } from 'react';
import type { MotionValue } from 'framer-motion';
import { findLatestActiveLineIndex } from '../../../../utils/appPlaybackHelpers';
import { PlayerState } from '../../../../types';
import type { AudioBands, LyricData, StageLyricsSession } from '../../../../types';
import { setCurrentLineIndex, setHandoffLineIndex, setPlayerState } from '../../../../stores/usePlaybackStore';
import { selectDisplayLyrics, usePlaybackStore } from '../../../../stores/usePlaybackStore';
import {
    audioBands,
    audioPower,
    currentTime,
    handoffLyricCurrentTime,
    handoffProgress,
    lyricCurrentTime,
} from '../../../../stores/motionSignals';
import { getTransitionHandoffProgress } from '../../../../services/automix/transitionCue';
import { omni } from '../../../../services/onlineMusic/omni';
import { tickBeatFx } from '../../../../services/beatFx/beatFxLive';
import { useBeatFxTrack } from '../../../../hooks/useBeatFxTrack';
import { readIncomingLyricClock } from './incomingLyricClock';
import { isBackgroundLyricHeld, setHeldLyricTime, useBackgroundLyricHoldStore } from '../../backgroundThrottling/backgroundLyricHoldStore';
import { getHifiPosition } from '../../../../services/hifi/hifiPlayback';
import { getExternalPosition, isExternalPlaybackSounding } from '../../../../services/onlineMusic/externalPlayback';

// src/components/app/playback/bridges/usePlaybackVisualizerBridge.ts

/**
 * How often the loop runs while 后台节流 holds the lyric animation. Only the clocks are kept then (the
 * progress bar, stage end, mods' playback time), and a timer keeps them going in a hidden window,
 * where frames stop.
 */
const HELD_TICK_MS = 250;

type UsePlaybackVisualizerBridgeParams = {

    audioRef: MutableRefObject<HTMLAudioElement | null>;
    analyserRef: MutableRefObject<AnalyserNode | null>;
    animationFrameRef: MutableRefObject<number>;
    effectiveLoopMode: 'off' | 'all' | 'one';
    isNowPlayingStageActive: boolean;
    isPlayerCapStageActive: boolean;
    stageActiveEntryKind: string | null;
    stageLyricsSession: StageLyricsSession | null;
    stageLyricsClockRef: MutableRefObject<{
        startTimeSec: number;
        endTimeSec: number;
        baseTimeSec: number;
        startedAtMs: number | null;
    }>;
    getSyntheticStageLyricsTime: () => number;
    syncStageLyricsClock: (timeSec: number, endTimeSec: number, nextPlayerState: PlayerState, startTimeSec?: number) => void;
    getNowPlayingDisplayTime: () => number;
    getPlayerCapDisplayTime: () => number;
    syncNowPlayingClock: (progressSec: number, durationSec: number, paused: boolean) => void;
    lyricTimelineOffsetMs: number;
    /**
     * The incoming track's own lyric offset during a blend (`lyricTimelineOffsetMs` is the displayed
     * track's): its clock is read against it, so it runs on unchanged when the settle makes it the
     * displayed track's. Left out, the displayed track's.
     */
    incomingLyricTimelineOffsetMs?: number;
    /** True while an automix handover is in progress and a deck other than the active one sounds. */
    isTransitionAudible: () => boolean;
    /**
     * The deck the on-screen track is playing on while a transition holds the picture, else null.
     *
     * The clock below has to follow whatever is on screen. From the moment a blend arms, the
     * active deck is seconds into the NEXT track while the title, cover and lyrics still belong to
     * the one finishing - so reading the active deck here puts the progress bar and the lyric
     * read-head near zero under a song that is three minutes in.
     */
    getDisplayElement?: () => HTMLAudioElement | null;
};

// Runs the requestAnimationFrame loop for audio-reactive visuals and lyric timing.
export function usePlaybackVisualizerBridge({
    audioRef,
    analyserRef,
    animationFrameRef,
    effectiveLoopMode,
    isNowPlayingStageActive,
    isPlayerCapStageActive,
    stageActiveEntryKind,
    stageLyricsSession,
    stageLyricsClockRef,
    getSyntheticStageLyricsTime,
    syncStageLyricsClock,
    getNowPlayingDisplayTime,
    getPlayerCapDisplayTime,
    syncNowPlayingClock,
    lyricTimelineOffsetMs,
    incomingLyricTimelineOffsetMs = lyricTimelineOffsetMs,
    isTransitionAudible,
    getDisplayElement,
}: UsePlaybackVisualizerBridgeParams) {
    // Read here rather than passed in: store fields and the module-level motion signals.
    const activePlaybackContext = usePlaybackStore(state => state.activePlaybackContext);
    const playerState = usePlaybackStore(state => state.playerState);
    const duration = usePlaybackStore(state => state.duration);
    // mpv sounds the song on the HiFi route: the decks are silent, and the clock is extrapolated from mpv's position.
    const isHifiActive = usePlaybackStore(state => state.playbackRoute) === 'hifi';
    // A provider's own player sounds it on the external route, with its own extrapolated clock.
    // Only once the app has shown the song: before that the old song still owns the lyric clock.
    const isExternalRouteActive = usePlaybackStore(state => state.playbackRoute) === 'external';
    const isExternalActive = isExternalRouteActive && isExternalPlaybackSounding();
    // The lyrics on screen, matching the deck getDisplayElement points at.
    const lyrics = usePlaybackStore(selectDisplayLyrics);
    // The live lyrics, which during a blend are the incoming track's (null until they load).
    const incomingLyrics = usePlaybackStore(state => state.lyrics);

    const currentLineIndexRef = useRef(-1);
    // 智能动感模式: loads the track's beats while it is on; the clock is stepped below. A ref, so
    // switching it does not rebuild the frame loop.
    const beatFxWantedRef = useRef(false);
    beatFxWantedRef.current = useBeatFxTrack();
    const handoffLineIndexRef = useRef(-1);
    // The lyric offsets as the loop reads them. The settle moves the displayed one onto the incoming
    // track's as it copies that track's clock: the prop catches up a render later, and a frame read in
    // between against the outgoing track's offset would move the line by the difference.
    const displayOffsetMsRef = useRef(lyricTimelineOffsetMs);
    const incomingOffsetMsRef = useRef(incomingLyricTimelineOffsetMs);
    useEffect(() => {
        displayOffsetMsRef.current = lyricTimelineOffsetMs;
    }, [lyricTimelineOffsetMs]);
    useEffect(() => {
        incomingOffsetMsRef.current = incomingLyricTimelineOffsetMs;
    }, [incomingLyricTimelineOffsetMs]);

    // A preview clip may start somewhere inside its song: the read-head is the deck's own clock plus
    // that start. Cached per URL until the registry changes, since the frame loop asks every frame.
    const clipStartSecRef = useRef(new Map<string, number>());
    const clipStartVersionRef = useRef(-1);
    const lyricClipStartSec = useCallback((element: HTMLAudioElement | null | undefined): number => {
        const src = element?.currentSrc;
        if (!src) return 0;
        const version = omni.audioSourceMetadataVersion();
        if (clipStartVersionRef.current !== version) {
            clipStartSecRef.current.clear();
            clipStartVersionRef.current = version;
        }
        const known = clipStartSecRef.current.get(src);
        if (known !== undefined) return known;
        const seconds = omni.previewClipStartMsOfAudioSource(src) / 1000;
        const starts = clipStartSecRef.current;
        starts.set(src, seconds);
        if (starts.size > 8) {
            const oldest = starts.keys().next().value;
            if (oldest !== undefined) starts.delete(oldest);
        }
        return seconds;
    }, []);

    // The ends of a blend, written as the store changes rather than on the next frame: the visualizer
    // renders from that same change, and a frame late it would draw the incoming track's lyrics from
    // the outgoing track's clock and line (or the last blend's finished hand-off at the next one's start).
    useEffect(() => usePlaybackStore.subscribe((state, previous) => {
        if (state.transitionDisplay === previous.transitionDisplay) return;
        if (previous.transitionDisplay === null) {
            handoffProgress.set(0);
            handoffLineIndexRef.current = -1;
            setHandoffLineIndex(-1);
            return;
        }
        if (state.transitionDisplay !== null) return;
        // Handed over: the picture is now the incoming track, and its clock runs on from its own deck.
        // Only the session knows which way the blend went. A cancel keeps the outgoing deck's clock, and
        // a skip mid-blend loads some other track onto the deck that was incoming, so both are left to
        // the ordinary song change. Read from the deck here rather than from the frame loop's last
        // hand-off: that loop does not run while the window is hidden.
        // The hand-off itself is left where it stood: what plays along it (the background change, the
        // Monet cover) lets go of it at a settle or a cancel and plays the rest from there on the clock,
        // and a set here would snap it to the end first.
        const incoming = audioRef.current;
        if (state.transitionEnd !== 'handedOver' || !incoming) return;
        const clock = readIncomingLyricClock(
            incoming.currentTime + lyricClipStartSec(incoming),
            incomingOffsetMsRef.current,
            state.lyrics?.lines,
        );
        displayOffsetMsRef.current = incomingOffsetMsRef.current;
        currentTime.set(incoming.currentTime);
        lyricCurrentTime.set(clock.lyricTimeSec);
        currentLineIndexRef.current = clock.lineIndex;
        setCurrentLineIndex(clock.lineIndex);
    }), [audioRef, lyricClipStartSec]);

    // The frame loop moves the read-head only while the deck plays. A deck that loads or seeks while
    // paused - a restored session, above all a restored preview clip, which starts somewhere inside
    // its song - would leave it where the song change put it (useLyricReadHead: the top of the whole
    // song), while the remote window and OBS, which read the deck's position, show the line it is
    // really at; pressing play would then jump the main read-head forward on its first frame. So the
    // read-head is also set from those two events, and a paused deck costs nothing per frame.
    // Listened for on the document in the capture phase (media events do not bubble, but they are
    // captured), so the listener follows whichever deck is active without re-binding at a deck swap.
    // Only the main player's own clock: a stage or PlayerCap clock is written by its own branch below.
    const pausedDeckSyncRef = useRef({ ownsClock: false, lyrics });
    pausedDeckSyncRef.current = {
        ownsClock: activePlaybackContext === 'main' && !isNowPlayingStageActive && !isPlayerCapStageActive,
        lyrics,
    };
    useEffect(() => {
        if (typeof document === 'undefined') return undefined;
        const syncPausedDeck = (event: Event) => {
            const element = audioRef.current;
            if (!element || event.target !== element || !element.paused) return;
            const { ownsClock, lyrics: displayedLyrics } = pausedDeckSyncRef.current;
            // While a blend holds the picture this deck is the incoming track, not the one on screen.
            if (!ownsClock || getDisplayElement?.()) return;
            const clock = readIncomingLyricClock(
                element.currentTime + lyricClipStartSec(element),
                displayOffsetMsRef.current,
                displayedLyrics?.lines,
            );
            lyricCurrentTime.set(clock.lyricTimeSec);
            if (displayedLyrics && clock.lineIndex !== currentLineIndexRef.current) {
                currentLineIndexRef.current = clock.lineIndex;
                setCurrentLineIndex(clock.lineIndex);
            }
        };
        document.addEventListener('loadedmetadata', syncPausedDeck, true);
        document.addEventListener('seeked', syncPausedDeck, true);
        return () => {
            document.removeEventListener('loadedmetadata', syncPausedDeck, true);
            document.removeEventListener('seeked', syncPausedDeck, true);
        };
    }, [audioRef, getDisplayElement, lyricClipStartSec]);

    const updateLoop = useCallback(() => {
        // 后台节流 holds the lyric animation while the window is minimised or hidden: the clocks below
        // keep running, while the lyric read-head, the line and the audio bands stay where they are
        // until the window is back on screen (the pass that lets go catches them up).
        const backgroundHold = isBackgroundLyricHeld();
        setHeldLyricTime(null);
        const showLyricTime = (seconds: number) => {
            if (backgroundHold) setHeldLyricTime(seconds);
            else lyricCurrentTime.set(seconds);
        };
        const showLine = (index: number) => {
            if (backgroundHold || index === currentLineIndexRef.current) return;
            currentLineIndexRef.current = index;
            setCurrentLineIndex(index);
        };

        // Normally the active deck; the outgoing one for as long as a blend holds the picture on
        // the track it is finishing, so that clock and picture never describe different songs.
        const audioElement = getDisplayElement?.() ?? audioRef.current;
        // Never on the HiFi route, so the spectrum keeps the idle breath there: there is no analyser on mpv's output.
        const isActuallyPlaying = !isHifiActive && !isExternalActive && Boolean(audioElement && !audioElement.paused && !audioElement.ended);
        // Mid-handover a deck can be loading while the other one is still sounding. The analyser
        // is downstream of both, so it has real signal: dropping to the idle breath here would put
        // a visible stutter at exactly the moment meant to be seamless.
        const hasAudibleSignal = isActuallyPlaying || isTransitionAudible();

        if (backgroundHold) {
            // The bands keep their last values: nothing draws from them while held.
        } else if (hasAudibleSignal && analyserRef.current) {
            const bufferLength = analyserRef.current.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);
            analyserRef.current.getByteFrequencyData(dataArray);
            audioBands.spectrum?.set(dataArray);

            const getEnergy = (minHz: number, maxHz: number): number => {
                const start = Math.floor(minHz / 21.5);
                const end = Math.floor(maxHz / 21.5);
                let sum = 0;
                for (let index = start; index <= end; index += 1) {
                    sum += dataArray[index];
                }
                const count = end - start + 1;
                return count > 0 ? sum / count : 0;
            };

            const bass = getEnergy(20, 150);
            const lowMid = getEnergy(150, 400);
            const mid = getEnergy(400, 1200);
            const vocal = getEnergy(1000, 3500);
            const treble = getEnergy(3500, 12000);

            const process = (value: number, boost = 2) => {
                const normalized = value / 255;
                return Math.pow(normalized, boost) * 255;
            };

            audioPower.set(process((bass + lowMid) / 2, 3));
            audioBands.bass.set(process(bass, 1.8));
            audioBands.lowMid.set(process(lowMid, 2));
            audioBands.mid.set(process(mid, 2));
            audioBands.vocal.set(process(vocal, 1.5));
            audioBands.treble.set(process(treble, 2));
        } else {
            const time = Date.now() / 2000;
            const breath = (Math.sin(time) + 1) * 20;
            audioPower.set(breath);
            audioBands.bass.set(breath);
            audioBands.lowMid.set(breath);
            audioBands.mid.set(breath);
            audioBands.vocal.set(breath);
            audioBands.treble.set(breath);
            audioBands.spectrum?.set(new Uint8Array(0));
        }

        if (isExternalRouteActive) {
            // A frame can retain the outgoing render while the companion already owns a new clock.
            // Freeze until announcement and the lyrics render agree, rather than rewinding the old song.
            if (!isExternalPlaybackSounding() || lyrics !== selectDisplayLyrics(usePlaybackStore.getState())) return;
            // As with mpv: every frame, paused or not (the player's clock stands still while it is
            // paused, and a seek moves it). The end is the player's own report, not this clock.
            const time = getExternalPosition();
            currentTime.set(time);

            const effectiveLyricTime = time - displayOffsetMsRef.current / 1000;
            showLyricTime(effectiveLyricTime);

            if (lyrics) {
                showLine(findLatestActiveLineIndex(lyrics.lines, effectiveLyricTime));
            }
        } else if (isHifiActive) {
            // Every frame, paused or not: the clock stands still while mpv is paused, and a seek while
            // paused moves it. No end handling here - mpv reports the end itself.
            const time = getHifiPosition();
            currentTime.set(time);

            const effectiveLyricTime = time - displayOffsetMsRef.current / 1000;
            showLyricTime(effectiveLyricTime);

            if (lyrics) {
                showLine(findLatestActiveLineIndex(lyrics.lines, effectiveLyricTime));
            }
        } else if (isActuallyPlaying && audioElement) {
            const time = audioElement.currentTime;
            currentTime.set(time);

            const effectiveLyricTime = time + lyricClipStartSec(audioElement) - displayOffsetMsRef.current / 1000;
            showLyricTime(effectiveLyricTime);

            if (lyrics) {
                showLine(findLatestActiveLineIndex(lyrics.lines, effectiveLyricTime));
            }
        } else if (isNowPlayingStageActive) {
            const nextTime = getNowPlayingDisplayTime();
            const hasReachedEnd = playerState === PlayerState.PLAYING && duration > 0 && nextTime >= duration;

            currentTime.set(nextTime);

            const effectiveLyricTime = nextTime - displayOffsetMsRef.current / 1000;
            showLyricTime(effectiveLyricTime);
            showLine(lyrics ? findLatestActiveLineIndex(lyrics.lines, effectiveLyricTime) : -1);

            if (hasReachedEnd) {
                if (effectiveLoopMode === 'one' || effectiveLoopMode === 'all') {
                    syncNowPlayingClock(0, duration, false);
                    currentTime.set(0);
                    if (lyrics) {
                        showLine(findLatestActiveLineIndex(lyrics.lines, 0));
                    }
                } else {
                    syncNowPlayingClock(duration, duration, true);
                    setPlayerState(PlayerState.PAUSED);
                }
            }
        } else if (isPlayerCapStageActive) {
            // PlayerCap: clock extrapolated from progress×duration; a passive source, looping/ending is driven by the external player, so no end/loop handling here.
            const nextTime = getPlayerCapDisplayTime();
            currentTime.set(nextTime);

            const effectiveLyricTime = nextTime - displayOffsetMsRef.current / 1000;
            showLyricTime(effectiveLyricTime);
            showLine(lyrics ? findLatestActiveLineIndex(lyrics.lines, effectiveLyricTime) : -1);
        } else if (activePlaybackContext === 'stage' && stageActiveEntryKind === 'lyrics' && stageLyricsSession) {
            // A session without lyrics (an external player's track whose lyrics are not found) still keeps time.
            const nextTime = getSyntheticStageLyricsTime();
            const clock = stageLyricsClockRef.current;
            const hasReachedEnd = playerState === PlayerState.PLAYING && nextTime >= clock.endTimeSec;

            currentTime.set(nextTime);

            // The pushed session's lyrics are timed on its own clock: no song offset is taken off, as the line
            // below takes none. Without this the visualizers' read-head stood at the start while the line moved (#1325).
            showLyricTime(nextTime);
            showLine(lyrics ? findLatestActiveLineIndex(lyrics.lines, nextTime) : -1);

            if (hasReachedEnd) {
                // An external player's clock is its own to restart: the loop mode does not replay it here.
                if (!stageLyricsSession.clock && (effectiveLoopMode === 'one' || effectiveLoopMode === 'all')) {
                    syncStageLyricsClock(clock.startTimeSec, clock.endTimeSec, PlayerState.PLAYING, clock.startTimeSec);
                    currentTime.set(clock.startTimeSec);
                    showLyricTime(clock.startTimeSec);
                    showLine(lyrics ? findLatestActiveLineIndex(lyrics.lines, clock.startTimeSec) : -1);
                } else {
                    syncStageLyricsClock(clock.endTimeSec, clock.endTimeSec, PlayerState.PAUSED, clock.startTimeSec);
                    setPlayerState(PlayerState.PAUSED);
                }
            }
        }

        if (beatFxWantedRef.current && !backgroundHold) {
            tickBeatFx(isActuallyPlaying ? audioElement : null, analyserRef.current?.context);
        }

        // While a blend holds the picture, the active deck is the incoming track: its hand-off, clock
        // and line for the visualizer, off this same frame rather than a second loop.
        const heldElement = getDisplayElement?.() ?? null;
        const incomingElement = heldElement ? audioRef.current : null;
        if (!backgroundHold && incomingElement && incomingElement !== heldElement) {
            handoffProgress.set(getTransitionHandoffProgress());
            const incomingClock = readIncomingLyricClock(
                incomingElement.currentTime + lyricClipStartSec(incomingElement),
                incomingOffsetMsRef.current,
                incomingLyrics?.lines,
            );
            handoffLyricCurrentTime.set(incomingClock.lyricTimeSec);
            if (incomingClock.lineIndex !== handoffLineIndexRef.current) {
                handoffLineIndexRef.current = incomingClock.lineIndex;
                setHandoffLineIndex(incomingClock.lineIndex);
            }
        }
    }, [
        activePlaybackContext,
        analyserRef,
        audioBands,
        audioPower,
        audioRef,
        currentTime,
        duration,
        effectiveLoopMode,
        getNowPlayingDisplayTime,
        getPlayerCapDisplayTime,
        getSyntheticStageLyricsTime,
        isNowPlayingStageActive,
        isPlayerCapStageActive,
        lyrics,
        incomingLyrics,
        playerState,
        setCurrentLineIndex,
        setPlayerState,
        stageActiveEntryKind,
        stageLyricsClockRef,
        stageLyricsSession,
        syncNowPlayingClock,
        syncStageLyricsClock,
        lyricCurrentTime,
        lyricClipStartSec,
        isTransitionAudible,
        getDisplayElement,
        isHifiActive,
        isExternalActive,
        isExternalRouteActive,
    ]);

    // Every frame normally; while 后台节流 holds the lyrics, a slow timer that keeps only the clocks. The
    // moment the hold lets go, one pass runs at once, so the lyrics have caught up before anything reads them.
    useEffect(() => {
        let heldTimer: number | undefined;
        const tick = () => {
            updateLoop();
            schedule();
        };
        const schedule = () => {
            if (isBackgroundLyricHeld()) {
                heldTimer = window.setTimeout(tick, HELD_TICK_MS);
            } else {
                animationFrameRef.current = requestAnimationFrame(tick);
            }
        };
        const cancel = () => {
            if (animationFrameRef.current) {
                cancelAnimationFrame(animationFrameRef.current);
                animationFrameRef.current = 0;
            }
            window.clearTimeout(heldTimer);
        };

        schedule();
        const unsubscribeHold = useBackgroundLyricHoldStore.subscribe((state, previous) => {
            if (state.held === previous.held) return;
            // A song change while held set the line in the store (-1) behind this loop's back; compare
            // against that, or a new song's first line that happens to match the held one is never written.
            if (!state.held) currentLineIndexRef.current = usePlaybackStore.getState().currentLineIndex;
            cancel();
            tick();
        });
        return () => {
            unsubscribeHold();
            cancel();
            setHeldLyricTime(null);
        };
    }, [animationFrameRef, updateLoop]);
}

