const VisualizerCladdagh: React.FC<VisualizerSharedProps> = (props) => {
    const {
        currentTime,
        currentLineIndex,
        lines,
        theme,
        subtitleTheme,
        showText = true,
        lyricsFontScale = 1.0,
        subtitleFontScale = 1,
        subtitleOverlayOpacity,
        subtitleOverlayBackground,
        subtitleUpcomingLyricsBlur,
        hideTranslationSubtitle,
        subtitleOverlayLayout,
        audioPower,
        audioBands,
        claddaghTuning = DEFAULT_CLADDAGH_TUNING,
        paused = false,
    } = props;

    // 圆环的位置（#1124）：画面宽、高的百分比，0 在正中。轴线和歌词一起挪。
    const positionX = claddaghTuning.positionX ?? 0;
    const positionY = claddaghTuning.positionY ?? 0;
    // 沿圆环的翻译（#1124）：只在开关打开时画，字体跟副字幕的主题。
    const showRingTranslation = claddaghTuning.showTranslation === true;
    const translationFontStack = resolveThemeTranslationFontStack(subtitleTheme ?? theme);
    const translationFontWeight = resolveThemeFontWeight(subtitleTheme ?? theme, 600);

    const centerNormalTiltDeg = 90 - claddaghTuning.ellipseTiltDeg;

    const isRawScaleRef = useRef(false);
    const glowIntensityRef = useRef(0);
    const normalizePower = useCallback((power: number) => {
        if (!Number.isFinite(power)) return 0;
        if (power > 1.0) {
            isRawScaleRef.current = true;
        }
        return Math.max(0, Math.min(1, isRawScaleRef.current ? power / 255 : power));
    }, []);

    const { activeLine, upcomingLine, recentCompletedLine, nextLines } = useVisualizerRuntime({
        currentTime,
        currentLineIndex,
        lines,
    });

    const isChorus = activeLine?.isChorus ?? false;

    const smoothedBass = useSpring(audioBands.bass, {
        stiffness: 150,
        damping: 25,
    });
    const smoothedVocal = useSpring(audioBands.vocal, {
        stiffness: 120,
        damping: 24,
    });
    const fontStack = resolveThemeFontStack(theme);
    const baseFontSize = 72 * lyricsFontScale;
    const fontWeight = resolveThemeFontWeight(theme, 700);
    const fontSpec = `${fontWeight} ${baseFontSize}px ${fontStack}`;

    const containerRef = useRef<HTMLDivElement>(null);
    const axisLineRef = useRef<HTMLDivElement>(null);
    const [dimensions, setDimensions] = useState({ width: 800, height: 600 });

    // Smoothly animate axis line color and scale in response to audio power
    useEffect(() => {
        const lineEl = axisLineRef.current;
        if (!lineEl) return;

        let frameId = 0;
        let lastGlowFrameMs = 0;

        const updateColors = () => {
            const bassPower = paused ? 0 : normalizePower(smoothedBass.get());
            const vocalPower = paused ? 0 : normalizePower(smoothedVocal.get());
            const fromColor = theme.primaryColor || '#ffffff';
            let toColor = theme.accentColor || '#ffffff';
            // If primary and accent are the same, try secondary
            if (toColor === fromColor && theme.secondaryColor) {
                toColor = theme.secondaryColor;
            }
            // If still the same, mix with white to guarantee visual color change on beats
            if (toColor === fromColor) {
                toColor = '#ffffff';
            }

            // Color response (using maximum of bass and vocal energy for high responsiveness)
            const colorPower = Math.max(bassPower, vocalPower);
            const colorDelta = Math.max(0, colorPower - 0.02);
            const colorRatio = Math.min(1.0, colorDelta / 0.58);

            // Mix between fromColor and toColor, pulsing alpha from 0.2 to 0.95 (vivid color beat)
            const mixed = mixColors(fromColor, toColor, colorRatio, 0.2 + 0.75 * colorRatio);

            // Linear-gradient fades out the line at its top-left and bottom-right endpoints (20% and 80%)
            // so that the endpoints of the short segment are smoothly blurred/faded.
            const gradientString = `linear-gradient(90deg, transparent, ${mixed} 20%, ${mixed} 80%, transparent)`;
            lineEl.style.background = gradientString;
            lineEl.style.backgroundImage = gradientString;

            // Square the bass power value to expand the dynamic range and prevent easy saturation for length scaling
            const bassSqr = bassPower * bassPower;

            // Apply dynamic length scaling using scaleX and subtle thickness scaling using scaleY
            const scaleX = 1.0 + bassSqr * 1.5;
            const scaleY = 1.0 + bassSqr * 0.5;
            lineEl.style.transform = `translate(-50%, -50%) rotate(${centerNormalTiltDeg}deg) scale(${scaleX}, ${scaleY})`;

            // Frame-rate-independent glow intensity transition (~330ms across 60Hz, 90Hz, and 120Hz)
            const nowMs = typeof performance !== 'undefined' ? performance.now() : Date.now();
            const dtSec = lastGlowFrameMs > 0 ? Math.min(0.1, Math.max(0.001, (nowMs - lastGlowFrameMs) / 1000)) : (1 / 60);
            lastGlowFrameMs = nowMs;
            const targetIntensity = isChorus ? 1.0 : 0.0;
            const diff = targetIntensity - glowIntensityRef.current;
            const step = dtSec * 3.0;
            if (Math.abs(diff) > step) {
                glowIntensityRef.current += Math.sign(diff) * step;
                glowIntensityRef.current = Math.max(0, Math.min(1, glowIntensityRef.current));
            } else {
                glowIntensityRef.current = targetIntensity;
            }

            const glowIntensity = glowIntensityRef.current;
            if (glowIntensity > 0.001) {
                const glowSize = (4 + bassPower * 12) * glowIntensity;
                const glowColor = colorWithAlpha(mixed, glowIntensity);
                lineEl.style.filter = `drop-shadow(0 0 ${glowSize.toFixed(1)}px ${glowColor})`;
            } else {
                lineEl.style.filter = 'none';
            }

            frameId = requestAnimationFrame(updateColors);
        };

        frameId = requestAnimationFrame(updateColors);

        return () => {
            cancelAnimationFrame(frameId);
        };
    }, [smoothedBass, smoothedVocal, theme.primaryColor, theme.accentColor, theme.secondaryColor, centerNormalTiltDeg, paused, isChorus, claddaghTuning.showAxisLine]);

    // Initialize dimensions on mount to avoid zero size on first render
    useEffect(() => {
        const container = containerRef.current;
        if (container) {
            const rect = container.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) {
                setDimensions({ width: rect.width, height: rect.height });
            }
        }
        // Track container dimensions responsively using ResizeObserver
        const observer = new ResizeObserver(entries => {
            const entry = entries[0];
            if (entry) {
                const { width, height } = entry.contentRect;
                if (width > 0 && height > 0) {
                    setDimensions({ width, height });
                }
            }
        });
        if (container) observer.observe(container);
        return () => observer.disconnect();
    }, []);

    // Radial configuration (increased to prevent long sentence overlaps)
    const Rx = (dimensions.width > 0 ? Math.min(dimensions.width * 0.44, 560) : 360) * claddaghTuning.radiusScale;
    const Ry = Rx > 0 ? Rx * 0.707 : 254; // 45-degree angle projection ratio
    const focusSpacingScale = (1 + claddaghTuning.focusScaleRatio) / (1 + DEFAULT_CLADDAGH_TUNING.focusScaleRatio);
    const activeTextSpacingScale = focusSpacingScale;

    if (typeof window !== 'undefined') {
        (window as any).visualizerDimensions = dimensions;
        (window as any).visualizerRx = Rx;
        (window as any).visualizerRy = Ry;
    }

    // Determine the focus line index
    const focusIndex = currentLineIndex !== -1
        ? currentLineIndex
        : (recentCompletedLine
            ? lines.indexOf(recentCompletedLine)
            : -1);
    const centerLineIndex = Math.max(-1, focusIndex);
    const [renderBaseIndex, setRenderBaseIndex] = useState(centerLineIndex);

    const activeSpacingInfo = useMemo(() => {
        const line = lines[renderBaseIndex];
        if (!line) return [];
        const timeline = adjustCladdaghTimeline(buildLineGraphemeTimeline(line), line);
        return buildMeasuredSpacingInfo(timeline, fontSpec, baseFontSize, Rx, activeTextSpacingScale, claddaghTuning.letterSpacingOffset);
    }, [lines, renderBaseIndex, fontSpec, baseFontSize, Rx, activeTextSpacingScale, claddaghTuning.letterSpacingOffset]);

    // Coordinate rotation offsets using MotionValue for line transition自转 animations
    const lineOffset = useMotionValue(centerLineIndex * Math.PI);
    const lastIndexRef = useRef(centerLineIndex);

    useEffect(() => {
        const prev = lastIndexRef.current;
        const curr = centerLineIndex;
        lastIndexRef.current = curr;

        if (Math.abs(curr - prev) > 1) {
            lineOffset.set(curr * Math.PI);
            setRenderBaseIndex(curr);
        } else {
            // Update renderBaseIndex immediately so activeSpacingInfo tracks
            // the new active line from the start. This prevents the wordOffset
            // discontinuity that occurred when onComplete switched it later.
            setRenderBaseIndex(curr);
            const controls = animate(lineOffset, curr * Math.PI, {
                type: 'spring',
                stiffness: 55,
                damping: 14,
                mass: 0.9,
            });
            return () => controls.stop();
        }
    }, [centerLineIndex, lineOffset]);

    // Keep the transition pair + one preceding line rendered so the outgoing
    // line remains visible during the spring rotation.
    const lineIndicesToRender = useMemo(() => {
        const indices = [];
        if (lines.length === 0) return [];
        for (let i = renderBaseIndex - 1; i <= renderBaseIndex + 2; i++) {
            if (i >= 0 && i < lines.length) {
                indices.push(i);
            }
        }
        if (indices.length === 0) {
            indices.push(Math.max(0, Math.min(centerLineIndex, lines.length - 1)));
        }
        return indices;
    }, [centerLineIndex, lines.length, renderBaseIndex]);

    return (
        <VisualizerShell
            theme={theme}
            audioPower={audioPower}
            audioBands={audioBands}
            sharedProps={props}
        >
            <motion.div
                initial={{ opacity: 0, scale: 0.96, filter: 'blur(4px)' }}
                animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
                exit={{ opacity: 0, scale: 1.04, filter: 'blur(4px)' }}
                transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
                ref={containerRef as any}
                className="relative flex flex-col items-center justify-center w-full h-full overflow-hidden select-none"
            >
                {/* Background Dedicated Visuals */}
                <div className="absolute inset-0 overflow-hidden pointer-events-none z-[1]">
                    {/* Center Axis Line with blurred/faded endpoints */}
                    {claddaghTuning.showAxisLine && (
                        <div
                            ref={axisLineRef}
                            style={{
                                position: 'absolute',
                                left: `${50 + positionX}%`,
                                top: `${50 + positionY}%`,
                                width: '300px',
                                height: '4px',
                                transform: `translate(-50%, -50%) rotate(${centerNormalTiltDeg}deg) scale(1, 1)`,
                                transformOrigin: 'center center',
                                willChange: 'background, transform, filter',
                            }}
                        />
                    )}
                </div>

                <div
                    style={{
                        width: '100%',
                        height: '100%',
                        position: 'relative',
                        zIndex: 10,
                        // Percentages of this box, which is the whole stage: the ring's centre moves by the tuning's share of it.
                        transform: positionX !== 0 || positionY !== 0 ? `translate(${positionX}%, ${positionY}%)` : undefined,
                    }}
                >
                    {showText && Rx > 0 && Ry > 0 && lineIndicesToRender.map(idx => (
                        <RingLine
                            key={idx}
                            line={lines[idx]}
                            lineIndex={idx}
                            centerLineIndex={centerLineIndex}
                            currentTime={currentTime}
                            lineOffset={lineOffset}
                            theme={theme}
                            lyricsFontScale={lyricsFontScale}
                            Rx={Rx}
                            Ry={Ry}
                            audioPower={smoothedBass}
                            containerWidth={dimensions.width}
                            containerHeight={dimensions.height}
                            activeSpacingInfo={activeSpacingInfo}
                            renderBaseIndex={renderBaseIndex}
                            lines={lines}
                            focusScaleRatio={claddaghTuning.focusScaleRatio}
                            ellipseTiltDeg={claddaghTuning.ellipseTiltDeg}
                            textSpacingScale={activeTextSpacingScale}
                            letterSpacingOffset={claddaghTuning.letterSpacingOffset}
                            translation={showRingTranslation ? lines[idx].translation : undefined}
                            translationFontStack={translationFontStack}
                            translationFontWeight={translationFontWeight}
                            translationScale={claddaghTuning.translationScale ?? 1}
                            translationLetterSpacingOffset={claddaghTuning.translationLetterSpacingOffset ?? 0}
                        />
                    ))}
                </div>
            </motion.div>

            {showText && (
                <VisualizerSubtitleOverlay
                    showText={showText}
                    activeLine={activeLine}
                    recentCompletedLine={recentCompletedLine}
                    nextLines={nextLines}
                    theme={theme}
                    subtitleTheme={subtitleTheme}
                    translationFontSize="clamp(1.1rem, 2.2vw, 1.45rem)"
                    upcomingFontSize="clamp(0.95rem, 1.8vw, 1.2rem)"
                    subtitleOverlayOpacity={subtitleOverlayOpacity}
                    subtitleOverlayBackground={subtitleOverlayBackground}
                    subtitleUpcomingLyricsBlur={subtitleUpcomingLyricsBlur}
                    subtitleFontScale={subtitleFontScale}
                    hideTranslationSubtitle={hideTranslationSubtitle}
                    subtitleOverlayLayout={subtitleOverlayLayout}
                />
            )}
        </VisualizerShell>
    );
};

export default VisualizerCladdagh;

src/components/visualizer/monet/MonetRai:
import React, { useMemo } from 'react';
import { motion, MotionValue } from 'framer-motion';
import { type Theme, type Line } from '../../../types';
import { SECONDARY_TRACK_OPACITY } from '../../../utils/lyrics/subtitleTrackStyle';
import { resolveLyricTextDirection } from '../../../utils/lyrics/textDirection';
import { colorWithAlpha } from '../../../utils/colorMix';
import { type WordColorMatcher } from '../wordColoring';
import { MONET_SCROLL_TRANSITION, MONET_SUBTITLE_TRACK_STAGGER_S, type PositionedMonetLineEntry } from './monetRailLayout';
import { composeLineMasks, getClippedTextMask, getEdgeFadeMask, getLineMask } from './monetRailMasks';
import { MonetTimedTokenSpan } from './MonetRailTokens';

// src/components/visualizer/monet/MonetRailLine.tsx
// 歌词栏中的一行：位置、缩放、模糊与副字幕轨，按行状态切换静态或扫字渲染。

/** The chorus glow's [alpha, at %] stops: falls off smoothly to nothing at the ellipse's edge. */
const CHORUS_GLOW_STOPS: Array<[number, number]> = [[0.14, 0], [0.12, 15], [0.085, 35], [0.05, 55], [0.022, 72], [0.007, 87]];

export const MonetRailLine: React.FC<{
    entry: PositionedMonetLineEntry;
    currentTime: MotionValue<number>;
    theme: Theme;
    lyricFontPx: number;
    fontStack: string;
    translationFontStack: string;
    glowBufferPx: number;
    vGlowBufferPx: number;
    fontsEpoch: number;
    wordColorMatchers: WordColorMatcher[];
    audioPower?: MotionValue<number>;
    onLineSeek?: (line: Line) => void;
    canSeek?: boolean;
    disableEntryMotion?: boolean;
    renderStaticPassed?: boolean;
    /** Mirrored layout (#1124): the line is set flush right and scales about its right edge. */
    alignEnd?: boolean;
}> = ({ entry, currentTime, theme, lyricFontPx, fontStack, translationFontStack, glowBufferPx, vGlowBufferPx, fontsEpoch, wordColorMatchers, audioPower, onLineSeek, canSeek = false, disableEntryMotion = false, renderStaticPassed = false, alignEnd = false }) => {
    const initialOffset = entry.offset >= 0 ? 34 : -34;
    const exitOffset = entry.status === 'passed' || entry.offset < 0 ? -38 : 38;
    // The active lyric must never be truncated, so its box is sized by its own wrapped
    // content instead of the pre-measured height, and it carries no truncation fade.
    // Context lines keep the fixed two-line box that keeps the rail compact.
    const isActiveLine = entry.status === 'active';
    // An RTL line (Uyghur, Arabic...) runs its words from the right edge and scales about it.
    const rtl = useMemo(() => resolveLyricTextDirection(entry.line.fullText) === 'rtl', [entry.line.fullText]);
    // Flush right: an RTL line, or any line of the mirrored layout. Its words still read in their own direction.
    const flushRight = rtl || alignEnd;
    const textMask = isActiveLine
        ? undefined
        : getClippedTextMask(
            entry.layout.isTextClipped,
            vGlowBufferPx + entry.layout.textPaddingTopPx + entry.layout.textContentHeightPx,
            Math.max(lyricFontPx * 0.55, 12),
        );
    const textEdgeMask = getEdgeFadeMask(entry.layout.isTextOverflowingWidth, Math.max(lyricFontPx * 0.9, 24), rtl);
    const textMaskStyle = composeLineMasks(textMask, textEdgeMask);
    const handleSeek = (event: React.MouseEvent | React.KeyboardEvent) => {
        if (!canSeek) {
            return;
        }

        event.stopPropagation();
        onLineSeek?.(entry.line);
    };
    const handleClickSeek = (event: React.MouseEvent<HTMLDivElement>) => {
        handleSeek(event);
        event.currentTarget.blur();
    };

    return (
        <motion.div
            role={canSeek ? 'button' : undefined}
            tabIndex={canSeek ? 0 : undefined}
            onClick={canSeek ? handleClickSeek : undefined}
            onKeyDown={canSeek ? (event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    handleSeek(event);
                }
            } : undefined}
            className={`absolute top-0 min-w-0 will-change-transform ${canSeek ? 'cursor-pointer' : ''}`}
            initial={disableEntryMotion ? false : {
                opacity: 0,
                y: entry.y + initialOffset,
                scale: entry.tone.scale * 0.98,
                filter: 'blur(5px)',
            }}
            animate={{
                opacity: entry.tone.opacity,
                y: entry.y,
                scale: entry.tone.scale,
                filter: `blur(${entry.tone.blurPx}px)`,
            }}
            exit={disableEntryMotion ? undefined : {
                opacity: 0,
                y: entry.y + exitOffset,
                scale: entry.tone.scale * 0.98,
                filter: 'blur(6px)',
                transition: { duration: 0.2, ease: [0.32, 0.72, 0, 1] },
            }}
            transition={MONET_SCROLL_TRANSITION}
            style={{
                left: `${glowBufferPx}px`,
                right: `${glowBufferPx}px`,
                height: entry.layout.visualHeightPx,
                transformOrigin: flushRight ? 'right top' : 'left top',
                zIndex: entry.tone.zIndex,
            }}
        >
            {entry.line.isChorus && (
                <motion.div
                    className="absolute inset-x-0 -inset-y-14 pointer-events-none -z-10"
                    initial={{ opacity: 0 }}
                    animate={{
                        opacity: entry.status === 'active' ? 1 : 0,
                        scale: entry.status === 'active' ? 1.02 : 0.96,
                    }}
                    transition={{ duration: 0.45, ease: 'easeOut' }}
                    style={{
                        // An ellipse touching the box's sides, reaching past the line above and below,
                        // gone before any edge: no straight edge shows, and no blur is needed to hide one.
                        background: `radial-gradient(closest-side, ${CHORUS_GLOW_STOPS.map(([alpha, at]) => `${colorWithAlpha(theme.accentColor, alpha)} ${at}%`).join(', ')}, transparent 100%)`,
                    }}
                />
            )}
            <div
                dir={rtl ? 'rtl' : 'ltr'}
                className="min-w-0 overflow-hidden pointer-events-none"
                style={{
                    marginLeft: `-${glowBufferPx}px`,
                    marginRight: `-${glowBufferPx}px`,
                    paddingLeft: `${glowBufferPx}px`,
                    paddingRight: `${glowBufferPx}px`,
                    marginTop: `-${vGlowBufferPx}px`,
                    marginBottom: `-${vGlowBufferPx}px`,
                    paddingTop: `${entry.layout.textPaddingTopPx + vGlowBufferPx}px`,
                    paddingBottom: `${entry.layout.textPaddingBottomPx + vGlowBufferPx}px`,
                    height: isActiveLine
                        ? undefined
                        : `${entry.layout.textHeightPx + vGlowBufferPx * 2}px`,
                    boxSizing: 'border-box',
                    fontFamily: fontStack,
                    fontSize: lyricFontPx,
                    fontWeight: entry.tone.fontWeight,
                    lineHeight: `${entry.layout.lineHeightPx}px`,
                    letterSpacing: 0,
                    textAlign: alignEnd && !rtl ? 'right' : undefined,
                    ...textMaskStyle,
                    textShadow: entry.status === 'active'
                        ? `0 14px 34px ${colorWithAlpha(theme.backgroundColor, 0.22)}`
                        : 'none',
                }}
            >
                <MonetTimedTokenSpan
                    entry={entry}
                    currentTime={currentTime}
                    accentColor={colorWithAlpha(theme.primaryColor, 0.98)}
                    fontPx={lyricFontPx}
                    fontStack={fontStack}
                    fontsEpoch={fontsEpoch}
                    wordColorMatchers={wordColorMatchers}
                    isChorus={entry.line.isChorus}
                    chorusAccentColor={theme.accentColor}
                    audioPower={audioPower}
                    renderStaticPassed={renderStaticPassed}
                    rtl={rtl}
                />
            </div>
            {entry.layout.subtitleTracks.map((track, trackIndex) => {
                // Each row is cut at its own row cap, so the fade is per track. The second row steps
                // down in colour alpha too (0.68 is the single-row alpha); size and weight were set at measure time.
                const trackMask = getLineMask(track.isClipped, Math.max(track.fontPx * 0.65, 10));
                return (
                    <motion.div
                        key={track.role}
                        // The track reads in its own direction but sits on the lyric's side.
                        dir="auto"
                        data-subtitle-track={track.role}
                        className="min-w-0 overflow-hidden whitespace-pre-wrap break-words"
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.28, ease: [0.32, 0.72, 0, 1], delay: trackIndex * MONET_SUBTITLE_TRACK_STAGGER_S }}
                        style={{
                            marginLeft: `-${glowBufferPx}px`,
                            marginRight: `-${glowBufferPx}px`,
                            paddingLeft: `${glowBufferPx}px`,
                            paddingRight: `${glowBufferPx}px`,
                            height: track.heightPx,
                            paddingTop: track.paddingTopPx,
                            paddingBottom: track.paddingBottomPx,
                            boxSizing: 'border-box',
                            color: colorWithAlpha(theme.primaryColor, trackIndex > 0 ? 0.68 * SECONDARY_TRACK_OPACITY : 0.68),
                            textAlign: flushRight ? 'right' : 'left',
                            fontFamily: translationFontStack,
                            fontSize: track.fontPx,
                            fontWeight: track.fontWeight,
                            lineHeight: `${track.lineHeightPx}px`,
                            letterSpacing: 0,
                            WebkitMaskImage: trackMask,
                            maskImage: trackMask,
                            WebkitMaskRepeat: 'no-repeat',
                            maskRepeat: 'no-repeat',
                            WebkitMaskSize: '100% 100%',
                            maskSize: '100% 100%',
                        }}
                    >
                        {track.text}
                    </motion.div>
                );
            })}
        </motion.div>
    );
};

import React, { useMemo } from 'react';
import { motion, motionValue, useTransform, MotionValue } from 'framer-motion';
import { type GraphemeTiming } from '../../../utils/lyrics/graphemeTiming';
import { getLineRenderEndTime } from '../../../utils/lyrics/renderHints';
import { colorWithAlpha, mixColors } from '../../../utils/colorMix';
import { resolveMonetFillWidth, resolveMonetGlow } from './monetLyricMotion';
import { buildWordColorRangesFromMatchers, resolveTokenColorMap, type WordColorMatcher } from '../wordColoring';
import { buildMonetDisplayTokens, measureMonetGraphemeOffsets, resolveMonetSweepEdgeSoftness, resolveMonetSweepEnd, resolveMonetWordStatus, type MonetLineStatus } from './monetLyricsModel';
import type { PositionedMonetLineEntry } from './monetRailLayout';

// src/components/visualizer/monet/MonetRailTokens.tsx
// 行内的逐词渲染：按时间着色的 token 与当前行的扫字遮罩 / 填充 / glow。

/** A clock that never moves, for words whose look does not depend on the time. */
const STILL_TIME = motionValue(0);

export const MonetTimedTokenSpan: React.FC<{
    entry: PositionedMonetLineEntry;
    currentTime: MotionValue<number>;
    accentColor: string;
    fontPx: number;
    fontStack: string;
    fontsEpoch: number;
    wordColorMatchers: WordColorMatcher[];
    isChorus?: boolean;
    chorusAccentColor?: string;
    audioPower?: MotionValue<number>;
    renderStaticPassed?: boolean;
    /** The line runs right to left: each word's sweep fills from its right edge. */
    rtl?: boolean;
}> = ({ entry, currentTime, accentColor, fontPx, fontStack, fontsEpoch, wordColorMatchers, isChorus, chorusAccentColor, audioPower, renderStaticPassed = false, rtl = false }) => {
    const lineRenderEndTime = useMemo(() => getLineRenderEndTime(entry.line), [entry.line]);
    const tokens = useMemo(() => buildMonetDisplayTokens(entry.line), [entry.line]);
    const wordColorRanges = useMemo(
        () => buildWordColorRangesFromMatchers(entry.line.fullText, wordColorMatchers),
        [entry.line.fullText, wordColorMatchers],
    );
    const tokenColors = useMemo(
        () => resolveTokenColorMap(tokens, wordColorRanges),
        [tokens, wordColorRanges],
    );
    const fontSpec = useMemo(
        () => `${entry.tone.fontWeight} ${fontPx}px ${fontStack}`,
        [entry.tone.fontWeight, fontPx, fontStack],
    );

    const resolvedAccentColor = isChorus && chorusAccentColor
        ? mixColors(accentColor, chorusAccentColor, 0.48)
        : accentColor;

    return (
        <span className="block w-full min-w-0 max-w-full whitespace-pre-wrap break-words">
            {tokens.map(token => (
                renderStaticPassed ? (
                    <span
                        key={token.key}
                        style={{
                            color: token.timed
                                ? tokenColors.get(token.key) ?? resolvedAccentColor
                                : entry.tone.baseColor,
                        }}
                    >
                        {token.text}
                    </span>
                ) : token.timed && token.startTime !== null && token.endTime !== null ? (
                    <MonetWordSweep
                        key={token.key}
                        text={token.text}
                        startTime={token.startTime}
                        endTime={token.endTime}
                        graphemeTimings={token.graphemeTimings}
                        lineRenderEndTime={lineRenderEndTime}
                        currentTime={currentTime}
                        lineStatus={entry.status}
                        wordColor={tokenColors.get(token.key) ?? resolvedAccentColor}
                        baseColor={entry.tone.baseColor}
                        fontPx={fontPx}
                        fontSpec={fontSpec}
                        fontsEpoch={fontsEpoch}
                        isChorus={isChorus}
                        audioPower={audioPower}
                        rtl={rtl}
                    />
                ) : (
                    <span key={token.key} style={{ color: entry.tone.baseColor }}>
                        {token.text}
                    </span>
                )
            ))}
        </span>
    );
};

const MonetWordSweep: React.FC<{
    text: string;
    startTime: number;
    endTime: number;
    graphemeTimings: GraphemeTiming[];
    lineRenderEndTime: number;
    currentTime: MotionValue<number>;
    lineStatus: MonetLineStatus;
    wordColor: string;
    baseColor: string;
    fontPx: number;
    fontSpec: string;
    /** Bumped when web fonts load; measured offsets are stale until then. */
    fontsEpoch: number;
    isChorus?: boolean;
    audioPower?: MotionValue<number>;
    rtl: boolean;
}> = ({
    text,
    startTime,
    endTime,
    graphemeTimings,
    lineRenderEndTime,
    currentTime,
    lineStatus,
    wordColor,
    baseColor,
    fontPx,
    fontSpec,
    fontsEpoch,
    isChorus,
    audioPower,
    rtl,
}) => {
        const isLineActive = lineStatus === 'active';
        const sweepAngle = rtl ? '270deg' : '90deg';
        const canRenderGlow = lineStatus === 'active' || lineStatus === 'passed';
        const graphemeOffsets = useMemo(
            () => measureMonetGraphemeOffsets(text, fontPx, fontSpec),
            // eslint-disable-next-line react-hooks/exhaustive-deps -- fontsEpoch re-measures once the real face loads
            [text, fontPx, fontSpec, fontsEpoch],
        );

        // Only a line being sung moves with the clock, and only sung lines can still be glowing.
        // Every other word reads a clock that never ticks: its transforms already ignore the time
        // when the line is not active, so the values are the same, but dozens of words per rail no
        // longer each run four transforms on every frame. useTransform re-subscribes on every
        // render, so a word picks the live clock up on the render that makes its line active.
        const sweepTime = isLineActive ? currentTime : STILL_TIME;
        const glowTime = canRenderGlow ? currentTime : STILL_TIME;

        const wordStatus = useTransform(sweepTime, latest => (
            isLineActive ? resolveMonetWordStatus(latest, startTime, endTime) : lineStatus
        ));

        const wordProgress = useTransform(sweepTime, latest => {
            if (!isLineActive || latest <= startTime) return 0;
            if (latest >= endTime) return 1;
            return (latest - startTime) / Math.max(0.001, endTime - startTime);
        });

        const fillWidth = useTransform(sweepTime, latest => (
            isLineActive ? resolveMonetFillWidth(latest, startTime, endTime, graphemeOffsets, graphemeTimings) : 0
        ));

        const maskImage = useTransform(fillWidth, latest => {
            const edgeSoftness = resolveMonetSweepEdgeSoftness(fontPx);
            const fullWidth = graphemeOffsets[graphemeOffsets.length - 1] ?? 0;
            const sweepEnd = resolveMonetSweepEnd(latest, fullWidth, edgeSoftness);
            const solidEnd = Math.max(sweepEnd - edgeSoftness, 0);
            const featherStart = Math.max(sweepEnd - edgeSoftness * 0.55, 0);
            const featherEnd = Math.max(sweepEnd, 0);
            // Offsets run from the word's start: its left edge, or its right edge in an RTL word.
            return `linear-gradient(${sweepAngle}, rgba(0, 0, 0, 1) 0px, rgba(0, 0, 0, 1) ${solidEnd}px, rgba(0, 0, 0, 0.92) ${featherStart}px, rgba(0, 0, 0, 0) ${featherEnd}px, rgba(0, 0, 0, 0) 100%)`;
        });

        const fillGradient = useTransform(wordProgress, progress => {
            const color = mixColors(baseColor, wordColor, Math.min(progress, 1));
            return `linear-gradient(${sweepAngle}, ${color} 0%, ${colorWithAlpha(color, 0.92)} 68%, ${colorWithAlpha(color, 0.72)} 100%)`;
        });

        const resolvedBaseColor = useTransform(wordStatus, status =>
            (isLineActive && status === 'passed') || lineStatus === 'passed' ? wordColor : baseColor,
        );

        // The glow is its own layer under the text: a halo fixed at full strength, faded by opacity.
        // Interpolating the text-shadow itself repainted and re-rasterized every glowing word on every
        // frame (on a 120 Hz Mac, most of this mode's raster and ~70 ms/s of GPU process); opacity on
        // its own compositing layer is applied by the compositor. At full strength it is the old halo
        // exactly; below it the halo keeps the word colour instead of leaning towards the base colour.
        const glowOpacity = useTransform(glowTime, latest => {
            if (!canRenderGlow || latest <= startTime) return 0;
            return Math.max(0, resolveMonetGlow(latest, startTime, endTime, lineRenderEndTime));
        });
        // Composited only while it is lit, so idle words on the rail do not each hold a layer.
        const glowWillChange = useTransform(glowOpacity, opacity => (opacity > 0 ? 'opacity' : 'auto'));
        const glowHalo = useMemo(() => {
            const radiusOne = Math.round(fontPx * (isChorus ? 0.45 : 0.28));
            const radiusTwo = Math.round(fontPx * (isChorus ? 0.90 : 0.65));
            const glowColor = mixColors(baseColor, wordColor, 1, isChorus ? 1.0 : 0.88);
            return `0 0 ${radiusOne}px ${glowColor}, 0 0 ${radiusTwo}px ${glowColor}`;
        }, [baseColor, fontPx, isChorus, wordColor]);

        // Glyphs with deep descenders (g, j, p, y, and many CJK forms) sit below the line box
        // whenever the font's em box is taller than `line-height`, which drives half-leading
        // negative. `background-clip: text` paints no background outside the fill box and the mask
        // clips at the overlay's border box, so the sweep used to stop mid-glyph — more visibly the
        // larger the font. Grow both boxes, then pull the text back so its position is unchanged.
        const sweepOverflowPx = Math.round(fontPx * 0.5);

        return (
            <span className="relative inline-block whitespace-pre-wrap break-words">
                {canRenderGlow ? (
                    <motion.span
                        aria-hidden
                        className="pointer-events-none absolute inset-0 block whitespace-pre-wrap break-words"
                        style={{ color: 'transparent', textShadow: glowHalo, opacity: glowOpacity, willChange: glowWillChange }}
                    >
                        {text}
                    </motion.span>
                ) : null}
                {/* relative so the text paints above the absolutely positioned glow, as it did above its own shadow. */}
                <motion.span className="relative" style={{ color: resolvedBaseColor }}>
                    {text}
                </motion.span>
                {isLineActive ? (
                    <motion.span
                        aria-hidden
                        className="pointer-events-none absolute left-0 right-0 block whitespace-pre-wrap break-words"
                        style={{
                            top: -sweepOverflowPx,
                            bottom: -sweepOverflowPx,
                            paddingTop: sweepOverflowPx,
                            paddingBottom: sweepOverflowPx,
                            boxSizing: 'border-box',
                            WebkitMaskImage: maskImage,
                            maskImage,
                            WebkitMaskSize: '100% 100%',
                            maskSize: '100% 100%',
                            WebkitMaskRepeat: 'no-repeat',
                            maskRepeat: 'no-repeat',
                            textShadow: 'none',
                        }}
                    >
                        <motion.span
                            className="block whitespace-pre-wrap break-words"
                            style={{
                                marginTop: -sweepOverflowPx,
                                paddingTop: sweepOverflowPx,
                                paddingBottom: sweepOverflowPx,
                                color: 'transparent',
                                WebkitTextFillColor: 'transparent',
                                backgroundImage: fillGradient,
                                WebkitBackgroundClip: 'text',
                                backgroundClip: 'text',
                            }}
                        >
                            {text}
                        </motion.span>
                    </motion.span>
                ) : null}
            </span>
        );
    };

