import { useEffect, useMemo, useRef, useState, type Dispatch, type SetStateAction } from 'react';
import { generateThemeFromLyrics, isMissingAiApiKeyError } from '../services/aiText';
import { saveToCache } from '../services/db';
import { DualTheme, LyricData, SongResult, StatusMessage, Theme, ThemeMode } from '../types';
import { getCachedThemeState, getCachedThemeStateForSong, getLastDualTheme, getLastLegacyTheme, type ThemeCacheSongKey } from '../services/themeCache';
import { saveSyncedThemeForSong } from '../services/sync/syncRepository';
import {
    applyStoredAnimationIntensityToDualTheme,
    applyStoredAnimationIntensityToTheme,
    isThemeAnimationIntensity,
    readStoredLastAppliedThemePointer,
    readStoredThemeAutoGenerateEnabled,
    readStoredThemeAutoSwitchEnabled,
    readStoredThemeGenerationSource,
    resolveCustomThemePreferenceChange,
    resolveSongThemeAutoGenerateChange,
    resolveSongThemeAutoSwitchChange,
    saveStoredAnimationIntensity,
    saveStoredLastAppliedThemePointer,
    saveStoredThemeAutoGenerateEnabled,
    saveStoredThemeAutoSwitchEnabled,
    saveStoredThemeGenerationSource,
    type ThemeGenerationSource,
    type ThemePreferenceSwitchState,
} from '../services/themePreferences';
import { FALLBACK_AI_DUAL_THEME, sanitizeDualTheme, sanitizeTheme } from '../services/themeSanitizer';
import { extractColors } from '../utils/colorExtractor';
import { isPureMusicLyricText } from '../utils/lyrics/pureMusic';
import {
    buildThemeSourceModel,
    buildBuiltinDualTheme,
    buildDefaultCustomDualTheme,
    getBaseThemeForMode,
    resolveBgModeTheme,
} from './themeControllerState';
import { getPlaybackSongKey } from '../utils/appPlaybackGuards';
import { usePlaybackStore } from '../stores/usePlaybackStore';
import { setStatusMessage as setStatusMsg } from '../stores/useStatusMessageStore';
import { endThemeOverrideForUserChoice, useThemeOverrideStore } from '../stores/useThemeOverrideStore';
import { useStableCallbacks } from './useStableCallbacks';

type StatusSetter = Dispatch<SetStateAction<StatusMessage | null>>;
export type GenerateAIThemeOptions = {
    source?: 'manual' | 'auto';
    shouldApply?: () => boolean;
};

export type GenerateAIThemeResult =
    | { status: 'generated'; applied: boolean }
    | { status: 'skipped'; reason: 'in-flight' | 'empty-prompt' }
    | { status: 'failed' };

const CUSTOM_DUAL_THEME_KEY = 'custom_dual_theme';

// Keeps local theme operations successful when the optional sync server is unavailable.
const saveSyncedThemeWithoutBlocking = (...args: Parameters<typeof saveSyncedThemeForSong>) => {
    void saveSyncedThemeForSong(...args).catch((error) => {
        console.warn('[sync] Failed to upload theme:', error);
    });
};
const CUSTOM_THEME_PREFERRED_KEY = 'custom_theme_preferred';

const sanitizeCustomTheme = (
    theme: Theme,
    fallbackName: string,
    fallbackTheme: Theme,
): Theme => {
    const sanitized = sanitizeTheme(theme, {
        ...fallbackTheme,
        name: fallbackName,
        description: '',
        wordColors: [],
        lyricsIcons: [],
        provider: 'Custom',
    });

    return {
        ...sanitized,
        name: sanitized.name?.trim() || fallbackName,
        description: sanitized.description || '',
        provider: sanitized.provider || 'Custom',
    };
};

const sanitizeCustomDualTheme = (dualTheme: DualTheme): DualTheme => ({
    light: sanitizeCustomTheme(dualTheme.light, 'Theme Park Light', FALLBACK_AI_DUAL_THEME.light),
    dark: sanitizeCustomTheme(dualTheme.dark, 'Theme Park Dark', FALLBACK_AI_DUAL_THEME.dark),
});

const isValidTheme = (value: unknown): value is Theme => {
    if (!value || typeof value !== 'object') {
        return false;
    }

    const candidate = value as Partial<Theme>;
    return typeof candidate.name === 'string'
        && typeof candidate.backgroundColor === 'string'
        && typeof candidate.primaryColor === 'string'
        && typeof candidate.accentColor === 'string'
        && typeof candidate.secondaryColor === 'string'
        && (candidate.fontStyle === 'sans' || candidate.fontStyle === 'serif' || candidate.fontStyle === 'mono')
        && (candidate.animationIntensity === 'calm' || candidate.animationIntensity === 'normal' || candidate.animationIntensity === 'chaotic');
};

const readStoredCustomTheme = (): DualTheme | null => {
    const saved = localStorage.getItem(CUSTOM_DUAL_THEME_KEY);
    if (!saved) {
        return null;
    }

    try {
        const parsed = JSON.parse(saved) as Partial<DualTheme>;
        if (!isValidTheme(parsed.light) || !isValidTheme(parsed.dark)) {
            return null;
        }

        return applyStoredAnimationIntensityToDualTheme(sanitizeCustomDualTheme({
            light: parsed.light,
            dark: parsed.dark,
        }));
    } catch {
        return null;
    }
};

const readStoredCustomPreferred = () => localStorage.getItem(CUSTOM_THEME_PREFERRED_KEY) === 'true';

const getSelectedDualTheme = (dualTheme: DualTheme, isDaylight: boolean) => (
    isDaylight ? dualTheme.light : dualTheme.dark
);

/**
 * The theme the app shows in a mode (`isDaylight`), from the song's theme sources. A mod's theme
 * (`overrideTheme`, useThemeOverrideStore) is laid over all of them, except while the user prefers
 * their custom theme.
 */
export const resolveControllerTheme = ({
    bgMode,
    aiTheme,
    legacyTheme,
    customTheme,
    isDaylight,
    defaultTheme,
    daylightTheme,
    previousTheme,
    overrideTheme = null,
    customPreferred = false,
}: {
    bgMode: ThemeMode;
    aiTheme: DualTheme | null;
    legacyTheme: Theme | null;
    customTheme: DualTheme | null;
    isDaylight: boolean;
    defaultTheme: Theme;
    daylightTheme: Theme;
    previousTheme: Theme;
    overrideTheme?: DualTheme | null;
    customPreferred?: boolean;
}): Theme => {
    const normalizeTheme = (nextTheme: Theme) => applyStoredAnimationIntensityToTheme(nextTheme);

    if (overrideTheme && !(customPreferred && customTheme)) {
        return normalizeTheme(getSelectedDualTheme(overrideTheme, isDaylight));
    }

    // The AI fallback below keeps the previous theme's keyword colors and icons; a mod's theme that was just
    // taken off (its provider is `mod:<id>`, hostTheme.ts) lends it none.
    const carriedTheme = previousTheme.provider?.startsWith('mod:')
        ? { ...previousTheme, wordColors: [], lyricsIcons: [] }
        : previousTheme;

    if (bgMode === 'custom' && customTheme) {
        return normalizeTheme(getSelectedDualTheme(customTheme, isDaylight));
    }

    if (bgMode === 'ai') {
        if (aiTheme) {
            return normalizeTheme(getSelectedDualTheme(aiTheme, isDaylight));
        }

        if (legacyTheme) {
            return normalizeTheme(legacyTheme);
        }
    }

    // The default source is the built-in theme itself: an AI or legacy theme stays loaded so the
    // user can switch back to it, but lends none of its colors here (#947).
    return normalizeTheme(resolveBgModeTheme({
        mode: bgMode === 'custom' ? 'default' : bgMode,
        aiTheme,
        isDaylight,
        defaultTheme,
        daylightTheme,
        previousTheme: carriedTheme,
    }));
};

export function useThemeController({
    defaultTheme,
    daylightTheme,
    isDaylight,
    setDaylightPreference,
    coverUrl,
    t,
}: {
    defaultTheme: Theme;
    daylightTheme: Theme;
    isDaylight: boolean;
    setDaylightPreference: (enabled: boolean) => void;
    coverUrl?: string | null;
    t: (key: string, options?: Record<string, unknown>) => string;
}) {
    const getBaseTheme = () => getBaseThemeForMode({ defaultTheme, daylightTheme, isDaylight });
    const storedCustomTheme = useMemo(readStoredCustomTheme, []);
    const initialCustomTheme = useMemo(() => (
        storedCustomTheme ?? buildDefaultCustomDualTheme({ defaultTheme, daylightTheme })
    ), [daylightTheme, defaultTheme, storedCustomTheme]);
    const initialThemePreferenceState = useMemo<ThemePreferenceSwitchState>(() => {
        const customPreferred = Boolean(initialCustomTheme && readStoredCustomPreferred());
        if (customPreferred) {
            return {
                isCustomThemePreferred: true,
                songThemeAutoSwitchEnabled: false,
                songThemeAutoGenerateEnabled: false,
            };
        }

        const autoSwitchEnabled = readStoredThemeAutoSwitchEnabled();
        return {
            isCustomThemePreferred: false,
            songThemeAutoSwitchEnabled: autoSwitchEnabled,
            songThemeAutoGenerateEnabled: autoSwitchEnabled && readStoredThemeAutoGenerateEnabled(),
        };
    }, [initialCustomTheme]);

    const [theme, setTheme] = useState<Theme>(() => applyStoredAnimationIntensityToTheme(getBaseTheme()));
    const [aiTheme, setAiTheme] = useState<DualTheme | null>(null);
    const [legacyTheme, setLegacyTheme] = useState<Theme | null>(null);
    const [customTheme, setCustomTheme] = useState<DualTheme | null>(initialCustomTheme);
    const [isCustomThemePreferred, setIsCustomThemePreferred] = useState(initialThemePreferenceState.isCustomThemePreferred);
    const [songThemeAutoSwitchEnabled, setSongThemeAutoSwitchEnabled] = useState(initialThemePreferenceState.songThemeAutoSwitchEnabled);
    const [songThemeAutoGenerateEnabled, setSongThemeAutoGenerateEnabled] = useState(initialThemePreferenceState.songThemeAutoGenerateEnabled);
    const [themeGenerationSource, setThemeGenerationSource] = useState<ThemeGenerationSource>(() => readStoredThemeGenerationSource());
    const [bgMode, setBgMode] = useState<ThemeMode>(() => (
        initialCustomTheme && initialThemePreferenceState.isCustomThemePreferred ? 'custom' : 'default'
    ));
    const [currentSongHasLocalAiTheme, setCurrentSongHasLocalAiTheme] = useState(false);
    const [isGeneratingTheme, setIsGeneratingTheme] = useState(false);
    const themeOverride = useThemeOverrideStore(state => state.override);
    const overrideTheme = themeOverride?.theme ?? null;
    const customPreferredNow = isCustomThemePreferred && Boolean(customTheme);
    const activeThemeGenerationCountRef = useRef(0);
    const themeGenerationSongKeysRef = useRef(new Set<string>());

    const themeSourceModel = useMemo(() => buildThemeSourceModel({
        bgMode,
        aiTheme,
        legacyTheme,
        customTheme,
        isDaylight,
        defaultTheme,
        daylightTheme,
        currentSongHasLocalAiTheme,
    }), [aiTheme, bgMode, customTheme, daylightTheme, defaultTheme, isDaylight, legacyTheme, currentSongHasLocalAiTheme]);

    // The three switches are mutually constrained by the resolvers, so they are only ever written
    // together through applyPreferenceSwitchState -- which lets a ref mirror them exactly. Reading the
    // render-scoped state instead would make two resolver calls in one handler (config import applies
    // both song-theme flags back to back) both start from the pre-import snapshot, so the second
    // write would silently discard the first.
    const preferenceSwitchRef = useRef<ThemePreferenceSwitchState>(initialThemePreferenceState);

    const getPreferenceSwitchState = (): ThemePreferenceSwitchState => preferenceSwitchRef.current;

    const applyPreferenceSwitchState = (state: ThemePreferenceSwitchState) => {
        preferenceSwitchRef.current = state;
        setIsCustomThemePreferred(state.isCustomThemePreferred);
        setSongThemeAutoSwitchEnabled(state.songThemeAutoSwitchEnabled);
        setSongThemeAutoGenerateEnabled(state.songThemeAutoGenerateEnabled);
    };

    const beginThemeGeneration = () => {
        activeThemeGenerationCountRef.current += 1;
        setIsGeneratingTheme(true);
    };

    const endThemeGeneration = () => {
        activeThemeGenerationCountRef.current = Math.max(0, activeThemeGenerationCountRef.current - 1);
        setIsGeneratingTheme(activeThemeGenerationCountRef.current > 0);
    };

    useEffect(() => {
        if (customTheme) {
            localStorage.setItem(CUSTOM_DUAL_THEME_KEY, JSON.stringify(customTheme));
        } else {
            localStorage.removeItem(CUSTOM_DUAL_THEME_KEY);
        }
    }, [customTheme]);

    useEffect(() => {
        localStorage.setItem(CUSTOM_THEME_PREFERRED_KEY, String(isCustomThemePreferred && !!customTheme));
    }, [customTheme, isCustomThemePreferred]);

    useEffect(() => {
        saveStoredAnimationIntensity(theme.animationIntensity);
    }, [theme.animationIntensity]);

    useEffect(() => {
        saveStoredThemeAutoSwitchEnabled(songThemeAutoSwitchEnabled);
    }, [songThemeAutoSwitchEnabled]);

    useEffect(() => {
        saveStoredThemeAutoGenerateEnabled(songThemeAutoGenerateEnabled);
    }, [songThemeAutoGenerateEnabled]);

    useEffect(() => {
        saveStoredThemeGenerationSource(themeGenerationSource);
    }, [themeGenerationSource]);

    useEffect(() => {
        const pointer = bgMode === 'custom' && customTheme
            ? 'custom'
            : bgMode === 'ai' && (aiTheme || legacyTheme)
                ? 'ai'
                : 'default';
        saveStoredLastAppliedThemePointer(pointer);
    }, [aiTheme, bgMode, customTheme, legacyTheme]);

    // The override layer refuses mods while the user prefers their custom theme, and a mod's theme
    // already in place ends when that preference comes on (at start too: mods may apply before this runs).
    useEffect(() => {
        const overrideStore = useThemeOverrideStore.getState();
        overrideStore.setCustomPreferred(customPreferredNow);
        if (customPreferredNow) overrideStore.clearOverride({ kind: 'host' });
    }, [customPreferredNow]);

    useEffect(() => {
        setTheme(previousTheme => resolveControllerTheme({
            bgMode, aiTheme, legacyTheme, customTheme, isDaylight, defaultTheme, daylightTheme, previousTheme,
            overrideTheme, customPreferred: customPreferredNow,
        }));
    }, [aiTheme, bgMode, customTheme, daylightTheme, defaultTheme, isDaylight, legacyTheme, overrideTheme, customPreferredNow]);

    // The song's light and dark themes: the pair `theme` is picked from by the app's mode (a scene takes
    // the one that fits its own picture, whatever that mode).
    const songThemePair = useMemo((): DualTheme => {
        const sources = {
            bgMode, aiTheme, legacyTheme, customTheme, defaultTheme, daylightTheme, previousTheme: theme,
            overrideTheme, customPreferred: customPreferredNow,
        };
        return {
            light: resolveControllerTheme({ ...sources, isDaylight: true }),
            dark: resolveControllerTheme({ ...sources, isDaylight: false }),
        };
    }, [aiTheme, bgMode, customTheme, daylightTheme, defaultTheme, legacyTheme, theme, overrideTheme, customPreferredNow]);

    const handleToggleDaylight = (isLight: boolean) => {
        setDaylightPreference(isLight);
    };

    const handleBgModeChange = (mode: ThemeMode) => {
        if (mode === 'custom' && !customTheme) {
            return;
        }

        endThemeOverrideForUserChoice();
        setBgMode(mode);
    };

    const handleResetTheme = () => {
        endThemeOverrideForUserChoice();
        setAiTheme(null);
        setLegacyTheme(null);
        setBgMode('default');
    };

    const applyDefaultTheme = () => {
        endThemeOverrideForUserChoice();
        setAiTheme(null);
        setLegacyTheme(null);
        setBgMode('default');
        setStatusMsg({
            type: 'success',
            text: t('notifications.appliedDefaultTheme', { themeName: isDaylight ? 'Daylight Default' : 'Midnight Default' }),
        });
    };

    const applyDualTheme = (
        dualTheme: DualTheme,
        options?: { respectCustomPreference?: boolean }
    ) => {
        const normalizedDualTheme = applyStoredAnimationIntensityToDualTheme(sanitizeDualTheme(dualTheme));
        setLegacyTheme(null);
        setAiTheme(normalizedDualTheme);
        void saveToCache('last_dual_theme', normalizedDualTheme);
        const respectCustomPreference = options?.respectCustomPreference ?? true;
        if (!respectCustomPreference || !isCustomThemePreferred) {
            setBgMode('ai');
        }
    };

    const applyLegacyTheme = (
        nextLegacyTheme: Theme,
        options?: { respectCustomPreference?: boolean }
    ) => {
        const normalizedLegacyTheme = applyStoredAnimationIntensityToTheme(
            sanitizeTheme(nextLegacyTheme, FALLBACK_AI_DUAL_THEME.dark),
        );
        setAiTheme(null);
        setLegacyTheme(normalizedLegacyTheme);
        void saveToCache('last_theme', normalizedLegacyTheme);
        const respectCustomPreference = options?.respectCustomPreference ?? true;
        if (!respectCustomPreference || !isCustomThemePreferred) {
            setBgMode('ai');
        }
    };

    const applyThemeFallback = () => {
        setAiTheme(null);
        setLegacyTheme(null);
        if (bgMode !== 'custom') {
            setBgMode('default');
        }
    };

    const getThemeParkSeedTheme = (): DualTheme => {
        if (bgMode === 'custom' && customTheme) {
            return customTheme;
        }

        if (aiTheme) {
            return aiTheme;
        }

        const baseDualTheme = applyStoredAnimationIntensityToDualTheme({
            light: {
                ...daylightTheme,
                wordColors: [],
                lyricsIcons: [],
            },
            dark: {
                ...defaultTheme,
                wordColors: [],
                lyricsIcons: [],
            },
        });

        if (legacyTheme) {
            if (isDaylight) {
                baseDualTheme.light = sanitizeCustomTheme({ ...legacyTheme }, legacyTheme.name || 'Theme Park Light', FALLBACK_AI_DUAL_THEME.light);
            } else {
                baseDualTheme.dark = sanitizeCustomTheme({ ...legacyTheme }, legacyTheme.name || 'Theme Park Dark', FALLBACK_AI_DUAL_THEME.dark);
            }
            return baseDualTheme;
        }

        if (isDaylight) {
            baseDualTheme.light = sanitizeCustomTheme({ ...theme }, theme.name || 'Theme Park Light', FALLBACK_AI_DUAL_THEME.light);
        } else {
            baseDualTheme.dark = sanitizeCustomTheme({ ...theme }, theme.name || 'Theme Park Dark', FALLBACK_AI_DUAL_THEME.dark);
        }

        return baseDualTheme;
    };

    const saveCustomDualTheme = (dualTheme: DualTheme) => {
        const sanitized = applyStoredAnimationIntensityToDualTheme(sanitizeCustomDualTheme(dualTheme));
        endThemeOverrideForUserChoice();
        setCustomTheme(sanitized);
        setBgMode('custom');
        setStatusMsg({
            type: 'success',
            text: t('notifications.savedCustomTheme', { themeName: getSelectedDualTheme(sanitized, isDaylight).name }),
        });
        return sanitized;
    };

    const saveEditedAiDualTheme = (
        dualTheme: DualTheme,
        songOrKey?: SongResult | ThemeCacheSongKey | null,
    ) => {
        const sanitized = applyStoredAnimationIntensityToDualTheme(sanitizeDualTheme(dualTheme));
        endThemeOverrideForUserChoice();
        setLegacyTheme(null);
        setAiTheme(sanitized);
        setBgMode('ai');
        void saveToCache('last_dual_theme', sanitized);
        const syncSong = songOrKey && typeof songOrKey === 'object' ? songOrKey : null;
        const songKey = syncSong ? getPlaybackSongKey(syncSong) : songOrKey;
        if (songKey != null) {
            void saveToCache(`dual_theme_${songKey}`, sanitized);
        }
        if (syncSong) {
            saveSyncedThemeWithoutBlocking(syncSong, sanitized, 'edited');
        }
        setStatusMsg({
            type: 'success',
            text: t('status.aiThemeUpdated', { themeName: getSelectedDualTheme(sanitized, isDaylight).name }),
        });
        return sanitized;
    };

    const applyCustomTheme = () => {
        if (!customTheme) {
            return;
        }

        endThemeOverrideForUserChoice();
        setBgMode('custom');
        setStatusMsg({
            type: 'success',
            text: t('notifications.appliedCustomTheme', { themeName: getSelectedDualTheme(customTheme, isDaylight).name }),
        });
    };

    const handleCustomThemePreferenceChange = (enabled: boolean) => {
        if (!customTheme && enabled) {
            return;
        }

        applyPreferenceSwitchState(resolveCustomThemePreferenceChange(getPreferenceSwitchState(), enabled));
        // Mirrored at once rather than a render later, so no mod's apply slips in between; a mod's theme ends
        // as the host's doing (the contract reports the preference coming on as `host`).
        const overrideStore = useThemeOverrideStore.getState();
        overrideStore.setCustomPreferred(enabled && Boolean(customTheme));
        if (enabled && customTheme) {
            overrideStore.clearOverride({ kind: 'host' });
            setBgMode('custom');
        }

        setStatusMsg({
            type: 'info',
            text: t('notifications.' + (enabled ? 'customThemePreferredOn' : 'customThemePreferredOff')),
        });
    };

    const handleSongThemeAutoSwitchChange = (enabled: boolean) => {
        applyPreferenceSwitchState(resolveSongThemeAutoSwitchChange(getPreferenceSwitchState(), enabled));
        setStatusMsg({
            type: 'info',
            text: t('notifications.' + (enabled ? 'autoSwitchThemeOn' : 'autoSwitchThemeOff')),
        });
    };

    const handleSongThemeAutoGenerateChange = (enabled: boolean) => {
        applyPreferenceSwitchState(resolveSongThemeAutoGenerateChange(getPreferenceSwitchState(), enabled));
        setStatusMsg({
            type: 'info',
            text: t('notifications.' + (enabled ? 'autoGenerateThemeOn' : 'autoGenerateThemeOff')),
        });
    };

    const handleThemeGenerationSourceChange = (source: ThemeGenerationSource) => {
        setThemeGenerationSource(source);
        setStatusMsg({
            type: 'info',
            text: t(source === 'cover' ? 'notifications.themeSourceCover' : 'notifications.themeSourceAi'),
        });
    };

    const restoreThemeFromLastAppliedPointer = async () => {
        const pointer = readStoredLastAppliedThemePointer();

        if (pointer === 'custom' && customTheme) {
            setBgMode('custom');
            return 'restored' as const;
        }

        if (pointer === 'ai') {
            const lastDualTheme = await getLastDualTheme();
            if (lastDualTheme) {
                applyDualTheme(lastDualTheme, { respectCustomPreference: false });
                return 'fallback-dual' as const;
            }

            const lastLegacyTheme = await getLastLegacyTheme();
            if (lastLegacyTheme) {
                applyLegacyTheme(lastLegacyTheme, { respectCustomPreference: false });
                return 'legacy' as const;
            }
        }

        setAiTheme(null);
        setLegacyTheme(null);
        setBgMode('default');
        return 'restored' as const;
    };

    const restoreCachedThemeForSong = async (
        songOrId: ThemeCacheSongKey | SongResult,
        options?: { allowLastUsedFallback?: boolean; preserveCurrentOnMiss?: boolean }
    ) => {
        if (!songThemeAutoSwitchEnabled) {
            if (options?.allowLastUsedFallback) {
                return restoreThemeFromLastAppliedPointer();
            }
            return 'restored' as const;
        }

        const cachedTheme = typeof songOrId === 'object'
            ? await getCachedThemeStateForSong(songOrId)
            : await getCachedThemeState(songOrId);

        if (cachedTheme.kind === 'dual') {
            setCurrentSongHasLocalAiTheme(true);
            applyDualTheme(cachedTheme.theme, { respectCustomPreference: false });
            return 'dual' as const;
        }

        if (cachedTheme.kind === 'legacy') {
            setCurrentSongHasLocalAiTheme(true);
            applyLegacyTheme(cachedTheme.theme, { respectCustomPreference: false });
            return 'legacy' as const;
        }

        setCurrentSongHasLocalAiTheme(false);

        // When auto-switching song themes is enabled and this song has no cached theme yet,
        // derive a faithful theme directly from the song's album cover artwork if available.
        const candidateSongObj = typeof songOrId === 'object' ? (songOrId as SongResult) : null;
        const songCoverCandidate = candidateSongObj?.album?.coverUrl || coverUrl || null;
        if (songCoverCandidate && !isCustomThemePreferred) {
            void (async () => {
                try {
                    const extracted = await extractColors(songCoverCandidate, 6);
                    if (extracted.length > 0) {
                        const autoCoverTheme = applyStoredAnimationIntensityToDualTheme(
                            buildBuiltinDualTheme({ coverColors: extracted }),
                        );
                        if (candidateSongObj) {
                            await saveToCache(`dual_theme_${getPlaybackSongKey(candidateSongObj)}`, autoCoverTheme);
                        }
                        applyDualTheme(autoCoverTheme, { respectCustomPreference: true });
                    }
                } catch {
                    // Ignore background cover extraction failure
                }
            })();
        }

        if (options?.allowLastUsedFallback) {
            const lastDualTheme = await getLastDualTheme();
            if (lastDualTheme) {
                applyDualTheme(lastDualTheme, { respectCustomPreference: false });
                return 'fallback-dual' as const;
            }

            const lastLegacyTheme = await getLastLegacyTheme();
            if (lastLegacyTheme) {
                applyLegacyTheme(lastLegacyTheme, { respectCustomPreference: false });
                return 'legacy' as const;
            }
        }

        if (options?.preserveCurrentOnMiss ?? true) {
            return 'none' as const;
        }

        applyThemeFallback();
        return 'none' as const;
    };

    const lastAutoCoverUrlRef = useRef<string | null>(null);
    useEffect(() => {
        if (!songThemeAutoSwitchEnabled || isCustomThemePreferred || !coverUrl) {
            return;
        }
        if (lastAutoCoverUrlRef.current === coverUrl) {
            return;
        }
        lastAutoCoverUrlRef.current = coverUrl;
        if (currentSongHasLocalAiTheme) {
            return;
        }
        let cancelled = false;
        void extractColors(coverUrl, 6).then((extracted) => {
            if (cancelled || extracted.length === 0) return;
            const autoCoverTheme = applyStoredAnimationIntensityToDualTheme(
                buildBuiltinDualTheme({ coverColors: extracted }),
            );
            applyDualTheme(autoCoverTheme, { respectCustomPreference: true });
        }).catch(() => {});
        return () => {
            cancelled = true;
        };
    }, [coverUrl, currentSongHasLocalAiTheme, isCustomThemePreferred, songThemeAutoSwitchEnabled]);

    // Cover-derived theme: the no-AI path. Shared by the "cover" generation source the user can
    // pick and by the fallback taken when the AI call fails for a missing API key.
    const applyCoverDerivedTheme = async (
        currentSong: SongResult | null,
        shouldApply: () => boolean,
        origin: 'chosen' | 'fallback',
        manual: boolean,
    ): Promise<GenerateAIThemeResult> => {
        const targetCover = coverUrl || currentSong?.album?.coverUrl || null;
        const coverColors = targetCover ? await extractColors(targetCover, 6) : [];
        const coverTheme = applyStoredAnimationIntensityToDualTheme(buildBuiltinDualTheme({ coverColors }));

        if (currentSong) {
            await saveToCache(`dual_theme_${getPlaybackSongKey(currentSong)}`, coverTheme);
            saveSyncedThemeWithoutBlocking(currentSong, coverTheme, 'fallback');
        }

        if (!shouldApply()) {
            return { status: 'generated', applied: false };
        }

        if (currentSong) {
            setCurrentSongHasLocalAiTheme(true);
        }
        // A theme the user asked for themselves ends a mod's theme; an automatic one stays under it.
        if (manual) endThemeOverrideForUserChoice();
        applyDualTheme(coverTheme);
        const customPreferred = bgMode === 'custom' && customTheme;
        setStatusMsg(origin === 'fallback'
            ? {
                type: 'info',
                text: customPreferred
                    ? t('notifications.aiThemeGeneratedCustomPreferred')
                    : t('status.aiFallbackThemeUsed'),
            }
            : {
                type: 'success',
                text: customPreferred
                    ? t('notifications.aiThemeUpdatedCustomPreferred')
                    : t('status.coverThemeApplied', {
                        themeName: getSelectedDualTheme(coverTheme, isDaylight).name,
                    }),
            });

        return { status: 'generated', applied: true };
    };

    const generateAITheme = async (
        lyrics: LyricData | null,
        currentSong: SongResult | null,
        options: GenerateAIThemeOptions = {},
    ): Promise<GenerateAIThemeResult> => {
        const source = options.source ?? 'manual';
        const songKey = currentSong ? getPlaybackSongKey(currentSong) : '__no_song__';
        // Read playback at completion time, even before React has rendered the next song.
        // A late result may populate its own cache, but must not update another song's UI.
        const shouldApply = () => {
            const latestSong = usePlaybackStore.getState().currentSong;
            const latestSongKey = latestSong ? getPlaybackSongKey(latestSong) : '__no_song__';
            return latestSongKey === songKey && (options.shouldApply?.() ?? true);
        };
        if (themeGenerationSongKeysRef.current.has(songKey)) {
            return { status: 'skipped', reason: 'in-flight' };
        }

        themeGenerationSongKeysRef.current.add(songKey);
        beginThemeGeneration();
        setStatusMsg({ type: 'info', text: t('status.generatingTheme') });
        try {
            // The cover source never touches the model, so it also never needs a lyric prompt:
            // an instrumental with no title still gets a theme from its artwork.
            if (themeGenerationSource === 'cover') {
                return await applyCoverDerivedTheme(
                    currentSong,
                    shouldApply,
                    'chosen',
                    source === 'manual',
                );
            }

            const allText = lyrics?.lines.map(line => line.fullText).join('\n').trim() || '';
            const songTitle = currentSong?.name?.trim() || lyrics?.title?.trim() || '';
            const isPureMusic = Boolean(currentSong?.isPureMusic) || isPureMusicLyricText(allText);
            const promptText = (isPureMusic ? songTitle : allText) || allText;

            if (!promptText) {
                if (source === 'manual') {
                    setStatusMsg({ type: 'error', text: t('status.themeGenerationFailed') });
                }
                return { status: 'skipped', reason: 'empty-prompt' };
            }

            const dualTheme = await generateThemeFromLyrics(promptText, {
                isPureMusic,
                songTitle: songTitle || undefined,
            });
            const normalizedDualTheme = applyStoredAnimationIntensityToDualTheme(sanitizeDualTheme(dualTheme));
            if (currentSong) {
                await saveToCache(`dual_theme_${getPlaybackSongKey(currentSong)}`, normalizedDualTheme);
                saveSyncedThemeWithoutBlocking(currentSong, normalizedDualTheme, source === 'auto' ? 'auto' : 'manual');
            }

            if (!shouldApply()) {
                return { status: 'generated', applied: false };
            }

            if (currentSong) {
                setCurrentSongHasLocalAiTheme(true);
            }
            if (source === 'manual') endThemeOverrideForUserChoice();
            applyDualTheme(normalizedDualTheme);

            const selectedTheme = getSelectedDualTheme(normalizedDualTheme, isDaylight);
            setStatusMsg({
                type: 'success',
                text: bgMode === 'custom' && customTheme
                    ? t('notifications.aiThemeUpdatedCustomPreferred')
                    : t('status.themeApplied', { themeName: selectedTheme.name }),
            });

            return { status: 'generated', applied: true };
        } catch (error: unknown) {
            console.error(error);
            if (isMissingAiApiKeyError(error)) {
                return await applyCoverDerivedTheme(
                    currentSong,
                    shouldApply,
                    'fallback',
                    source === 'manual',
                );
            }

            if (shouldApply()) {
                setStatusMsg({ type: 'error', text: t('status.themeGenerationFailed') });
            }
            return { status: 'failed' };
        } finally {
            themeGenerationSongKeysRef.current.delete(songKey);
            endThemeGeneration();
        }
    };

    const setThemeWithStoredIntensity = (nextTheme: Theme) => {
        if (isThemeAnimationIntensity(nextTheme.animationIntensity)) {
            saveStoredAnimationIntensity(nextTheme.animationIntensity);
        }
        setTheme(applyStoredAnimationIntensityToTheme(nextTheme));
    };

    // Every one of these is invoked from an event, an effect or async work - never read during
    // render for its identity - so a permanent identity is safe here and is what lets the five
    // build*Model memos in App.tsx hold. Before this they changed on every render of this hook,
    // which cascaded into playSong and from there into all four view models.
    const actions = useStableCallbacks({
        setTheme: setThemeWithStoredIntensity,
        setAiTheme,
        setBgMode,
        handleToggleDaylight,
        handleBgModeChange,
        handleResetTheme,
        applyDefaultTheme,
        applyDualTheme,
        applyLegacyTheme,
        applyThemeFallback,
        restoreCachedThemeForSong,
        generateAITheme,
        getThemeParkSeedTheme,
        saveCustomDualTheme,
        saveEditedAiDualTheme,
        applyCustomTheme,
        handleCustomThemePreferenceChange,
        handleSongThemeAutoSwitchChange,
        handleSongThemeAutoGenerateChange,
        handleThemeGenerationSourceChange,
    });

    return {
        theme,
        songThemePair,
        aiTheme,
        customTheme,
        hasCustomTheme: Boolean(customTheme),
        themeSourceModel,
        isCustomThemePreferred,
        songThemeAutoSwitchEnabled,
        songThemeAutoGenerateEnabled,
        themeGenerationSource,
        bgMode,
        isGeneratingTheme,
        /** A mod's theme shown over the song's theme (Folium 1.10 `folium.theme.apply`), or null. */
        themeOverride: customPreferredNow ? null : themeOverride,
        ...actions,
    };
}

src/services/android/androidSafDirectory:
import { getOpfsRootName, isSerializedOpfsHandle } from '../webOpfsImport';
import { isAndroidNativeApp } from '../../utils/platform';
import {
    buildAndroidSafStreamUrl,
    checkAndroidDirectoryPermission,
    checkAndroidFileReadable,
    extractAndroidAudioMetadata,
    pickAndroidMusicSource,
    readAndroidContentUriBytes,
    resolveAndroidRelativeFile,
    scanAndroidDirectoryTree,
    type FoliaAndroidExtractedMetadata,
    type FoliaSafEntryDescriptor,
} from './foliaAndroidBridge';

// src/services/android/androidSafDirectoryHandle.ts
// Implements FileSystemDirectoryHandle and FileSystemFileHandle over Android's Storage Access
// Framework (SAF) with persisted URI permissions, structured-cloneable IndexedDB persistence,
// bounded header-slice metadata reads, and direct byte-range stream URL resolution.

export interface SerializedAndroidSafDirectoryHandle {
    __foliaAndroidSafHandle: true;
    kind: 'directory';
    name: string;
    treeUri: string;
    documentId: string;
    relativePrefix?: string;
    virtualEntries?: FoliaSafEntryDescriptor[];
}

export interface AndroidSafFileHandle extends FileSystemFileHandle {
    readonly __foliaAndroidSafFileHandle: true;
    readonly kind: 'file';
    readonly name: string;
    readonly contentUri: string;
    readonly treeUri: string;
    readonly documentId: string;
    readonly relativePath: string;
    readonly size: number;
    readonly lastModified: number;
    readonly mimeType: string;
    getStatMetadata(): { name: string; size: number; lastModified: number; type: string };
    canStreamDirectly(): boolean;
    getPlayableStreamUrl(): string;
    verifyReadable(): Promise<boolean>;
    /**
     * Reads only a bounded header slice of the audio file for metadata/tag inspection so
     * multi-megabyte lossless files are never loaded in full into the WebView JS heap.
     */
    getMetadataFile(options?: { includeCover?: boolean; maxBytes?: number }): Promise<File>;
    /**
     * Uses Android's native off-thread MediaMetadataRetriever (when available) to extract
     * tags and downscaled cover art without reading the audio stream into JS memory.
     */
    extractNativeMetadata(options?: { includeCover?: boolean; maxCoverDimension?: number }): Promise<FoliaAndroidExtractedMetadata | null>;
}

export interface AndroidSafDirectoryHandle extends FileSystemDirectoryHandle, Omit<SerializedAndroidSafDirectoryHandle, 'kind' | 'name'> {
    queryPermission(descriptor?: { mode?: 'read' | 'readwrite' }): Promise<PermissionState>;
    requestPermission(descriptor?: { mode?: 'read' | 'readwrite' }): Promise<PermissionState>;
    invalidateTreeCache(): void;
}

const normalizeRelativePath = (value: string): string => (
    value.replace(/\\/g, '/').replace(/^\/+|\/+$/g, '')
);

const inferAudioOrLyricMimeType = (fileName: string, providedMime?: string): string => {
    if (providedMime && providedMime !== 'application/octet-stream') {
        return providedMime;
    }
    const lower = fileName.toLowerCase();
    if (lower.endsWith('.mp3')) return 'audio/mpeg';
    if (lower.endsWith('.flac')) return 'audio/flac';
    if (lower.endsWith('.m4a') || lower.endsWith('.aac')) return 'audio/mp4';
    if (lower.endsWith('.alac')) return 'audio/alac';
    if (lower.endsWith('.wav')) return 'audio/wav';
    if (lower.endsWith('.aif') || lower.endsWith('.aiff')) return 'audio/aiff';
    if (lower.endsWith('.caf')) return 'audio/x-caf';
    if (lower.endsWith('.ogg')) return 'audio/ogg';
    if (lower.endsWith('.opus')) return 'audio/opus';
    if (lower.endsWith('.wma')) return 'audio/x-ms-wma';
    if (lower.endsWith('.wv')) return 'audio/x-wavpack';
    if (lower.endsWith('.ape')) return 'audio/x-monkeys-audio';
    if (lower.endsWith('.tta')) return 'audio/x-tta';
    if (lower.endsWith('.png')) return 'image/png';
    if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
    if (lower.endsWith('.webp')) return 'image/webp';
    if (lower.endsWith('.ttml')) return 'application/ttml+xml';
    if (lower.endsWith('.vtt')) return 'text/vtt';
    return 'text/plain';
};

export const isAndroidSafFileHandle = (handle: unknown): handle is AndroidSafFileHandle => (
    Boolean(handle && typeof handle === 'object' && (handle as AndroidSafFileHandle).__foliaAndroidSafFileHandle === true)
);

export const isAndroidSafDirectoryHandle = (handle: unknown): handle is AndroidSafDirectoryHandle => (
    Boolean(handle && typeof handle === 'object' && (handle as SerializedAndroidSafDirectoryHandle).__foliaAndroidSafHandle === true)
);

/**
 * Shared tree entry cache keyed by `treeUri::documentId` so handle recovery and nested directory
 * lookups reuse the scanned entries in O(1) without triggering repeated native full-tree scans.
 */
const sharedTreeEntriesCache = new Map<string, Promise<FoliaSafEntryDescriptor[]>>();

export const invalidateAndroidSafTreeCache = (treeUri?: string): void => {
    if (!treeUri) {
        sharedTreeEntriesCache.clear();
        return;
    }
    for (const key of Array.from(sharedTreeEntriesCache.keys())) {
        if (key === treeUri || key.startsWith(`${treeUri}::`)) {
            sharedTreeEntriesCache.delete(key);
        }
    }
};

/**
 * Creates a lightweight stat-only File object for initial directory snapshot diffing so scanning
 * a large folder does not read multi-megabyte audio, lyric, or cover payloads into memory before diffing signatures.
 */
const createBrowserOrNodeFile = (
    parts: BlobPart[],
    name: string,
    options: { type: string; lastModified: number },
): File => {
    if (typeof File === 'function') {
        return new File(parts, name, options);
    }
    const blob = new Blob(parts, { type: options.type });
    return Object.assign(blob, {
        name,
        lastModified: options.lastModified,
        webkitRelativePath: '',
    }) as unknown as File;
};

export interface TaggedStatFile extends File {
    readonly __foliaSafStatFile?: boolean;
    readonly __foliaSafHandle?: AndroidSafFileHandle;
}

export const createLightweightStatFile = (handle: AndroidSafFileHandle): TaggedStatFile => {
    const stat = handle.getStatMetadata();
    const file = createBrowserOrNodeFile([], stat.name, {
        type: stat.type,
        lastModified: stat.lastModified,
    }) as TaggedStatFile;
    Object.defineProperty(file, 'size', {
        configurable: true,
        enumerable: true,
        value: stat.size,
    });
    Object.defineProperty(file, '__foliaSafStatFile', {
        configurable: true,
        enumerable: false,
        value: true,
    });
    Object.defineProperty(file, '__foliaSafHandle', {
        configurable: true,
        enumerable: false,
        value: handle,
    });
    return file;
};

/**
 * Resolves a real File with actual bytes if the given File was created via `createLightweightStatFile`
 * during fast snapshot tree traversal.
 */
export const ensureLoadedSafFile = async (file: File): Promise<File> => {
    const tagged = file as TaggedStatFile;
    if (tagged?.__foliaSafStatFile && tagged.__foliaSafHandle) {
        return await tagged.__foliaSafHandle.getFile();
    }
    return file;
};

/** Default bounded header slice sizes for tag-only vs embedded-cover metadata inspection. */
export const METADATA_HEADER_SLICE_NO_COVER_BYTES = 256 * 1024;
export const METADATA_HEADER_SLICE_WITH_COVER_BYTES = 1536 * 1024;

export const createAndroidSafFileHandle = (
    entry: FoliaSafEntryDescriptor,
    treeUri: string,
): AndroidSafFileHandle => {
    const mimeType = inferAudioOrLyricMimeType(entry.name, entry.mimeType);
    const relativePath = normalizeRelativePath(entry.relativePath || entry.name);
    const statSize = Number(entry.size) || 0;
    const statLastModified = Number(entry.lastModified) || 0;

    return {
        __foliaAndroidSafFileHandle: true,
        kind: 'file',
        name: entry.name,
        contentUri: entry.contentUri,
        treeUri,
        documentId: entry.documentId,
        relativePath,
        size: statSize,
        lastModified: statLastModified,
        mimeType,
        getStatMetadata() {
            return {
                name: entry.name,
                size: statSize,
                lastModified: statLastModified,
                type: mimeType,
            };
        },
        canStreamDirectly() {
            return isAndroidNativeApp() && Boolean(entry.contentUri);
        },
        getPlayableStreamUrl() {
            return buildAndroidSafStreamUrl(entry.contentUri, treeUri, mimeType);
        },
        async verifyReadable() {
            const status = await checkAndroidFileReadable(entry.contentUri, treeUri);
            return Boolean(status.readable);
        },
        async getFile(): Promise<File> {
            const bytes = await readAndroidContentUriBytes(entry.contentUri, treeUri, mimeType);
            return createBrowserOrNodeFile([bytes as unknown as BlobPart], entry.name, {
                type: mimeType,
                lastModified: statLastModified || Date.now(),
            });
        },
        async getMetadataFile(options?: { includeCover?: boolean; maxBytes?: number }): Promise<File> {
            const includeCover = options?.includeCover ?? false;
            const defaultMax = includeCover
                ? METADATA_HEADER_SLICE_WITH_COVER_BYTES
                : METADATA_HEADER_SLICE_NO_COVER_BYTES;
            const maxBytes = options?.maxBytes ?? defaultMax;
            const boundedLimit = statSize > 0 ? Math.min(statSize, maxBytes) : maxBytes;
            const bytes = await readAndroidContentUriBytes(entry.contentUri, treeUri, mimeType, {
                offset: 0,
                maxBytes: boundedLimit,
            });
            return createBrowserOrNodeFile([bytes as unknown as BlobPart], entry.name, {
                type: mimeType,
                lastModified: statLastModified || Date.now(),
            });
        },
        async extractNativeMetadata(options?: { includeCover?: boolean; maxCoverDimension?: number }): Promise<FoliaAndroidExtractedMetadata | null> {
            return await extractAndroidAudioMetadata(entry.contentUri, options);
        },
        async isSameEntry(other: FileSystemHandle): Promise<boolean> {
            return isAndroidSafFileHandle(other) && other.contentUri === entry.contentUri;
        },
        createWritable(): Promise<FileSystemWritableFileStream> {
            return Promise.reject(new Error('Read-only Android SAF file handle'));
        },
    } as AndroidSafFileHandle;
};

export const createAndroidSafDirectoryHandle = (
    init: {
        name: string;
        treeUri: string;
        documentId: string;
        relativePrefix?: string;
        virtualEntries?: FoliaSafEntryDescriptor[];
        sharedEntriesLoader?: () => Promise<FoliaSafEntryDescriptor[]>;
    },
): AndroidSafDirectoryHandle => {
    const relativePrefix = normalizeRelativePath(init.relativePrefix || '');
    const rootDocId = init.documentId.includes('/') ? init.documentId.split('/')[0]! : init.documentId;
    const cacheKey = `${init.treeUri}::${rootDocId}`;

    const loadAllTreeEntries = (): Promise<FoliaSafEntryDescriptor[]> => {
        if (init.sharedEntriesLoader) {
            return init.sharedEntriesLoader();
        }
        if (Array.isArray(init.virtualEntries)) {
            return Promise.resolve(init.virtualEntries);
        }
        let cached = sharedTreeEntriesCache.get(cacheKey);
        if (!cached) {
            cached = scanAndroidDirectoryTree(init.treeUri, rootDocId).catch((err) => {
                sharedTreeEntriesCache.delete(cacheKey);
                throw err;
            });
            sharedTreeEntriesCache.set(cacheKey, cached);
        }
        return cached;
    };

    const listDirectChildren = async (): Promise<Array<AndroidSafDirectoryHandle | AndroidSafFileHandle>> => {
        const allEntries = await loadAllTreeEntries();
        const directSubdirectories = new Map<string, FoliaSafEntryDescriptor | null>();
        const directFiles = new Map<string, FoliaSafEntryDescriptor>();

        for (const entry of allEntries) {
            const rel = normalizeRelativePath(entry.relativePath || entry.name);
            if (!rel) continue;

            let remainder: string;
            if (!relativePrefix) {
                remainder = rel;
            } else if (rel.startsWith(`${relativePrefix}/`)) {
                remainder = rel.slice(relativePrefix.length + 1);
            } else {
                continue;
            }

            if (!remainder) continue;
            const slashIndex = remainder.indexOf('/');
            if (slashIndex === -1) {
                if (entry.kind === 'directory') {
                    if (!directSubdirectories.has(remainder)) {
                        directSubdirectories.set(remainder, entry);
                    }
                } else {
                    directFiles.set(remainder, entry);
                }
            } else {
                const childDirName = remainder.slice(0, slashIndex);
                if (childDirName && !directSubdirectories.has(childDirName)) {
                    directSubdirectories.set(childDirName, null);
                }
            }
        }

        const results: Array<AndroidSafDirectoryHandle | AndroidSafFileHandle> = [];

        for (const [dirName, dirDescriptor] of directSubdirectories.entries()) {
            const childPrefix = relativePrefix ? `${relativePrefix}/${dirName}` : dirName;
            results.push(
                createAndroidSafDirectoryHandle({
                    name: dirName,
                    treeUri: init.treeUri,
                    documentId: dirDescriptor?.documentId || `${rootDocId}/${childPrefix}`,
                    relativePrefix: childPrefix,
                    virtualEntries: init.virtualEntries,
                    sharedEntriesLoader: loadAllTreeEntries,
                }),
            );
        }

        for (const [, fileEntry] of directFiles.entries()) {
            results.push(createAndroidSafFileHandle(fileEntry, init.treeUri));
        }

        return results;
    };

    const handle: AndroidSafDirectoryHandle = {
        __foliaAndroidSafHandle: true,
        kind: 'directory',
        name: init.name,
        treeUri: init.treeUri,
        documentId: init.documentId,
        ...(relativePrefix ? { relativePrefix } : {}),
        ...(init.virtualEntries ? { virtualEntries: init.virtualEntries } : {}),

        invalidateTreeCache() {
            invalidateAndroidSafTreeCache(init.treeUri);
        },

        async queryPermission(): Promise<PermissionState> {
            if (Array.isArray(init.virtualEntries) && init.virtualEntries.length > 0 && !init.treeUri.startsWith('content://')) {
                return 'granted';
            }
            const status = await checkAndroidDirectoryPermission(init.treeUri);
            return status.granted && status.exists ? 'granted' : 'prompt';
        },

        async requestPermission(): Promise<PermissionState> {
            if (Array.isArray(init.virtualEntries) && init.virtualEntries.length > 0 && !init.treeUri.startsWith('content://')) {
                return 'granted';
            }
            const status = await checkAndroidDirectoryPermission(init.treeUri);
            return status.granted && status.exists ? 'granted' : 'denied';
        },

        async isSameEntry(other: FileSystemHandle): Promise<boolean> {
            if (!isAndroidSafDirectoryHandle(other)) return false;
            return other.treeUri === init.treeUri
                && normalizeRelativePath(other.relativePrefix || '') === relativePrefix;
        },

        async *values(): AsyncIterableIterator<FileSystemDirectoryHandle | FileSystemFileHandle> {
            const children = await listDirectChildren();
            for (const child of children) {
                yield child;
            }
        },

        async *entries(): AsyncIterableIterator<[string, FileSystemDirectoryHandle | FileSystemFileHandle]> {
            const children = await listDirectChildren();
            for (const child of children) {
                yield [child.name, child];
            }
        },

        async *keys(): AsyncIterableIterator<string> {
            const children = await listDirectChildren();
            for (const child of children) {
                yield child.name;
            }
        },

        async getDirectoryHandle(name: string): Promise<FileSystemDirectoryHandle> {
            const cleanName = normalizeRelativePath(name);
            if (!cleanName) {
                throw new DOMException('Invalid directory name', 'TypeMismatchError');
            }
            const childPrefix = relativePrefix ? `${relativePrefix}/${cleanName}` : cleanName;
            return createAndroidSafDirectoryHandle({
                name: cleanName,
                treeUri: init.treeUri,
                documentId: `${rootDocId}/${childPrefix}`,
                relativePrefix: childPrefix,
                virtualEntries: init.virtualEntries,
                sharedEntriesLoader: loadAllTreeEntries,
            });
        },

        async getFileHandle(name: string): Promise<FileSystemFileHandle> {
            const cleanName = normalizeRelativePath(name);
            const targetRelativePath = relativePrefix ? `${relativePrefix}/${cleanName}` : cleanName;

            if (Array.isArray(init.virtualEntries)) {
                const match = init.virtualEntries.find(
                    entry => entry.kind === 'file' && normalizeRelativePath(entry.relativePath || entry.name) === targetRelativePath,
                );
                if (match) return createAndroidSafFileHandle(match, init.treeUri);
                throw new DOMException(`File not found: ${targetRelativePath}`, 'NotFoundError');
            }

            if (sharedTreeEntriesCache.has(cacheKey)) {
                const entries = await sharedTreeEntriesCache.get(cacheKey)!;
                const match = entries.find(
                    entry => entry.kind === 'file' && normalizeRelativePath(entry.relativePath || entry.name) === targetRelativePath,
                );
                if (match) return createAndroidSafFileHandle(match, init.treeUri);
            }

            const resolved = await resolveAndroidRelativeFile(init.treeUri, targetRelativePath);
            if (resolved && resolved.kind === 'file') {
                return createAndroidSafFileHandle(resolved, init.treeUri);
            }

            // Fallback: check full tree scan in case the provider uses non-hierarchical document IDs.
            const entries = await loadAllTreeEntries();
            const fallbackMatch = entries.find(
                entry => entry.kind === 'file' && normalizeRelativePath(entry.relativePath || entry.name) === targetRelativePath,
            );
            if (fallbackMatch) {
                return createAndroidSafFileHandle(fallbackMatch, init.treeUri);
            }

            throw new DOMException(`File not found in Android SAF tree: ${targetRelativePath}`, 'NotFoundError');
        },

        removeEntry(): Promise<void> {
            return Promise.reject(new DOMException('Read-only Android SAF directory handle', 'NoModificationAllowedError'));
        },

        resolve(): Promise<string[] | null> {
            return Promise.resolve(null);
        },

        [Symbol.asyncIterator]() {
            return handle.entries();
        },
    } as unknown as AndroidSafDirectoryHandle;

    return handle;
};

/** Prompts the user to pick an Android folder or multi-file set and returns an AndroidSafDirectoryHandle. */
export const pickAndroidDirectoryHandle = async (): Promise<AndroidSafDirectoryHandle> => {
    const picked = await pickAndroidMusicSource();
    if (!picked) {
        const abortError = new Error('The user aborted a request.');
        abortError.name = 'AbortError';
        throw abortError;
    }

    if (picked.mode === 'tree') {
        invalidateAndroidSafTreeCache(picked.directory.treeUri);
        return createAndroidSafDirectoryHandle({
            name: picked.directory.name,
            treeUri: picked.directory.treeUri,
            documentId: picked.directory.documentId,
        });
    }

    return createAndroidSafDirectoryHandle({
        name: picked.filesResult.rootName || 'Selected Music',
        treeUri: picked.filesResult.treeUri,
        documentId: picked.filesResult.documentId || 'picked-files',
        virtualEntries: picked.filesResult.files,
    });
};

/** Converts any AndroidSafDirectoryHandle instances in a map to plain JSON objects for IndexedDB storage. */
export const serializeDirHandlesForStorage = (
    handles: Record<string, FileSystemDirectoryHandle>,
): Record<string, FileSystemDirectoryHandle | SerializedAndroidSafDirectoryHandle> => {
    const output: Record<string, FileSystemDirectoryHandle | SerializedAndroidSafDirectoryHandle> = {};
    for (const [rootName, handle] of Object.entries(handles)) {
        if (isAndroidSafDirectoryHandle(handle)) {
            output[rootName] = {
                __foliaAndroidSafHandle: true,
                kind: 'directory',
                name: handle.name,
                treeUri: handle.treeUri,
                documentId: handle.documentId,
                ...(handle.relativePrefix ? { relativePrefix: handle.relativePrefix } : {}),
                ...(handle.virtualEntries ? { virtualEntries: handle.virtualEntries } : {}),
            };
        } else if (getOpfsRootName(handle)) {
            output[rootName] = { __foliaOpfsHandle: true, kind: 'directory', name: getOpfsRootName(handle)! } as unknown as FileSystemDirectoryHandle;
        } else {
            output[rootName] = handle;
        }
    }
    return output;
};

/** Rehydrates serialized Android SAF directory records read from IndexedDB back into live handles. */
export const rehydrateDirHandlesFromStorage = (
    stored: Record<string, FileSystemDirectoryHandle | SerializedAndroidSafDirectoryHandle> | null | undefined,
): Record<string, FileSystemDirectoryHandle> => {
    if (!stored || typeof stored !== 'object') return {};
    const output: Record<string, FileSystemDirectoryHandle> = {};
    for (const [rootName, value] of Object.entries(stored)) {
        if (isAndroidSafDirectoryHandle(value)) {
            output[rootName] = createAndroidSafDirectoryHandle({
                name: value.name || rootName,
                treeUri: value.treeUri,
                documentId: value.documentId || '',
                relativePrefix: value.relativePrefix,
                virtualEntries: value.virtualEntries,
            });
        } else if (isSerializedOpfsHandle(value)) {
            // Resolved to a live handle by getDirHandles (async).
            output[rootName] = value as unknown as FileSystemDirectoryHandle;
        } else if (value) {
            output[rootName] = value as FileSystemDirectoryHandle;
        }
    }
    return output;
};

