import type { LocalCoverAssetBackend } from '../types/localCover';
import { isBlob } from '../utils/blobGuards';
import { deleteAndroidDiskCacheEntry } from './android/foliaAndroidBridge';
import { ensureCoverMipmapsAndPalettePersisted } from './persistentDiskCacheService';

// src/services/localCoverBinaryStore.ts
// Persists canonical local covers outside IndexedDB with the same validated layout used by stable URLs,
// and triggers native Android 256x256 + 1024x1024 WebP mipmap & Monet palette generation in
// context.getFilesDir()/media_cache/{covers,palettes}/.

const ASSET_ID_PATTERN = /^sha256:([0-9a-f]{64})$/;
const ALLOWED_MIME_TYPES = new Set([
  'image/avif',
  'image/bmp',
  'image/gif',
  'image/jpeg',
  'image/png',
  'image/webp',
]);
const OPFS_ROOT_DIRECTORY = 'folia-cache';
const OPFS_LOCAL_COVER_DIRECTORY = 'local-cover-assets';
const LOCAL_COVER_THUMBNAIL_SIZES = [512, 1024] as const;

export interface LocalCoverBinaryWriteResult {
  backend: LocalCoverAssetBackend;
  mimeType: string;
  size: number;
}

interface LocalCoverFileDescriptor {
  id: string;
  mimeType: string;
  size: number;
  updatedAt: number;
}

export const isValidLocalCoverAssetId = (value: unknown): value is string => (
  typeof value === 'string' && ASSET_ID_PATTERN.test(value)
);

export const normalizeLocalCoverMimeType = (value: unknown): string | null => {
  if (typeof value !== 'string') return null;
  const normalized = value.toLowerCase();
  return ALLOWED_MIME_TYPES.has(normalized) ? normalized : null;
};

const getAssetDigest = (assetId: string): string | null => ASSET_ID_PATTERN.exec(assetId)?.[1] || null;

const hasElectronBridge = (): boolean => (
  typeof window !== 'undefined'
  && typeof window.electron?.hasLocalCoverAsset === 'function'
  && typeof window.electron?.saveLocalCoverAsset === 'function'
  && typeof window.electron?.removeLocalCoverAsset === 'function'
);

export const isLocalCoverWebRuntimeSupported = (): boolean => {
  if (typeof window === 'undefined') return false;
  if (hasElectronBridge()) return false;
  const isLocalhost = ['localhost', '127.0.0.1', '[::1]'].includes(window.location.hostname);
  return (window.location.protocol === 'https:' || isLocalhost)
    && window.isSecureContext
    && typeof navigator.storage?.getDirectory === 'function';
};

export const isLocalCoverAssetRuntimeSupported = (): boolean => (
  hasElectronBridge() || isLocalCoverWebRuntimeSupported()
);

const getOpfsDirectory = async (create: boolean): Promise<FileSystemDirectoryHandle | null> => {
  if (!isLocalCoverWebRuntimeSupported()) return null;
  try {
    const root = await navigator.storage.getDirectory();
    const cacheRoot = await root.getDirectoryHandle(OPFS_ROOT_DIRECTORY, { create });
    return await cacheRoot.getDirectoryHandle(OPFS_LOCAL_COVER_DIRECTORY, { create });
  } catch {
    return null;
  }
};

const getFileNames = (assetId: string) => {
  const digest = getAssetDigest(assetId);
  return digest ? { data: `${digest}.bin`, metadata: `${digest}.json` } : null;
};

const readOpfsDescriptor = async (
  directory: FileSystemDirectoryHandle,
  assetId: string,
): Promise<{ descriptor: LocalCoverFileDescriptor; file: File } | null> => {
  const names = getFileNames(assetId);
  if (!names) return null;
  try {
    const [file, rawMetadata] = await Promise.all([
      directory.getFileHandle(names.data).then(handle => handle.getFile()),
      directory.getFileHandle(names.metadata).then(handle => handle.getFile()).then(value => value.text()),
    ]);
    const descriptor = JSON.parse(rawMetadata) as Partial<LocalCoverFileDescriptor>;
    const mimeType = normalizeLocalCoverMimeType(descriptor.mimeType);
    if (descriptor.id !== assetId || !mimeType || descriptor.size !== file.size || file.size <= 0) return null;
    return {
      descriptor: { id: assetId, mimeType, size: file.size, updatedAt: Number(descriptor.updatedAt) || 0 },
      file,
    };
  } catch {
    return null;
  }
};

export const hasLocalCoverBinary = async (assetId: string): Promise<boolean> => {
  if (!isValidLocalCoverAssetId(assetId)) return false;
  if (hasElectronBridge()) return window.electron!.hasLocalCoverAsset(assetId);
  const directory = await getOpfsDirectory(false);
  if (directory && (await readOpfsDescriptor(directory, assetId))) {
    return true;
  }
  const fallbackBlob = await fetchNativeCachedCoverBlob(assetId);
  return Boolean(fallbackBlob && fallbackBlob.size > 0);
};

const fetchNativeCachedCoverBlob = async (assetId: string): Promise<Blob | null> => {
  if (typeof fetch !== 'function' || typeof window === 'undefined') return null;
  try {
    const resp = await fetch(`/__folia_cover/${encodeURIComponent(assetId)}?size=1024`);
    if (!resp.ok) return null;
    const contentType = resp.headers?.get?.('content-type') || '';
    if (contentType.includes('text/html')) return null;
    const blob = await resp.blob();
    return blob && blob.size > 0 ? blob : null;
  } catch {
    return null;
  }
};

/**
 * Reads a validated cover binary directly from OPFS (or Android's persistent WebP mipmap disk cache
 * at /__folia_cover/{assetId}) as a typed Blob.
 */
export const readLocalCoverBinaryBlob = async (assetId: string): Promise<Blob | null> => {
  if (!isValidLocalCoverAssetId(assetId)) return null;
  const directory = await getOpfsDirectory(false);
  if (directory) {
    const entry = await readOpfsDescriptor(directory, assetId);
    if (entry) {
      return entry.file.type === entry.descriptor.mimeType
        ? entry.file
        : new Blob([entry.file], { type: entry.descriptor.mimeType });
    }
  }
  return await fetchNativeCachedCoverBlob(assetId);
};

export const writeLocalCoverBinary = async (
  assetId: string,
  value: unknown,
): Promise<LocalCoverBinaryWriteResult | null> => {
  const mimeType = isBlob(value) ? normalizeLocalCoverMimeType(value.type) : null;
  if (!isValidLocalCoverAssetId(assetId) || !isBlob(value) || value.size <= 0 || !mimeType) return null;

  // Trigger native Android 256x256 + 1024x1024 WebP mipmap & Monet palette generation in background
  void ensureCoverMipmapsAndPalettePersisted(assetId, value);

  if (hasElectronBridge()) {
    await window.electron!.saveLocalCoverAsset(assetId, await value.arrayBuffer(), mimeType);
    return { backend: 'electron', mimeType, size: value.size };
  }

  const directory = await getOpfsDirectory(true);
  const names = getFileNames(assetId);
  if (!directory || !names) return null;
  const dataHandle = await directory.getFileHandle(names.data, { create: true });
  const metadataHandle = await directory.getFileHandle(names.metadata, { create: true });
  const dataWritable = await dataHandle.createWritable();
  try {
    await dataWritable.write(value);
    await dataWritable.close();
  } catch (error) {
    await dataWritable.abort().catch(() => undefined);
    throw error;
  }
  const descriptor: LocalCoverFileDescriptor = {
    id: assetId,
    mimeType,
    size: value.size,
    updatedAt: Date.now(),
  };
  const metadataWritable = await metadataHandle.createWritable();
  try {
    await metadataWritable.write(JSON.stringify(descriptor));
    await metadataWritable.close();
  } catch (error) {
    await metadataWritable.abort().catch(() => undefined);
    await directory.removeEntry(names.data).catch(() => undefined);
    throw error;
  }
  return { backend: 'opfs', mimeType, size: value.size };
};

export const removeLocalCoverBinary = async (assetId: string): Promise<void> => {
  if (!isValidLocalCoverAssetId(assetId)) return;
  void deleteAndroidDiskCacheEntry('covers', assetId);
  if (hasElectronBridge()) {
    await window.electron!.removeLocalCoverAsset(assetId);
    return;
  }
  const directory = await getOpfsDirectory(false);
  const names = getFileNames(assetId);
  if (!directory || !names) return;
  await Promise.all([
    directory.removeEntry(names.data).catch(() => undefined),
    directory.removeEntry(names.metadata).catch(() => undefined),
    ...LOCAL_COVER_THUMBNAIL_SIZES.map(size => (
      directory.removeEntry(`${names.data}.${size}.webp`).catch(() => undefined)
    )),
  ]);
};

export const clearLocalCoverBinaries = async (): Promise<void> => {
  void deleteAndroidDiskCacheEntry('covers', '*');
  if (hasElectronBridge()) {
    await window.electron!.clearLocalCoverAssets();
    return;
  }
  if (!isLocalCoverWebRuntimeSupported()) return;
  try {
    const root = await navigator.storage.getDirectory();
    const cacheRoot = await root.getDirectoryHandle(OPFS_ROOT_DIRECTORY);
    await cacheRoot.removeEntry(OPFS_LOCAL_COVER_DIRECTORY, { recursive: true });
  } catch {
    // A missing local-cover directory is already clear.
  }
};

import type { LocalSong } from '../types';
import type {
  LocalLibraryAssignment,
  LocalLibraryAssignmentOrigin,
  LocalLibraryEntity,
  LocalSongMetadataSource,
} from '../types/localLibrary';
import { buildLocalLibraryIndex, followEntityRedirect } from '../utils/localLibraryIndex';
import {
  cleanLocalLibraryName,
  getImportedAlbumName,
  getImportedArtistNames,
  splitLocalLibraryArtistNames,
} from '../utils/localLibraryNames';
import { appDatabase } from './appDatabase';
import { createLocalLibraryAssignment, resolveEntityNames } from './localLibraryCatalogInternals';
import { assignImportedSongs } from './localLibraryImportCatalog';
import { sanitizeLocalSongForStorage } from './repositories/localSongRepository';
import { deleteUnreferencedLocalCoverAssets } from './localCoverAssetService';
import {
  updatePersistedLibraryIndexSongs,
  writeOfflineSavedLyricsForSong,
} from './persistentDiskCacheService';

// src/services/localLibraryCatalogService.ts
// Applies every song/entity/assignment mutation in a single Dexie transaction and mirrors
// updated song records and matched lyrics to persistent disk cache for offline playback.

export { assignImportedSongs, ensureLocalLibraryInitialized, resetLocalLibraryInitializationCache } from './localLibraryImportCatalog';
export {
  mergeEntities,
  moveEntityMembersToExistingEntity,
  setEntityDisplayName,
  splitArtistEntityToTargets,
  splitEntity,
} from './localLibraryEntityMutations';

export interface MatchedLocalMetadata {
  source?: LocalSongMetadataSource;
  title?: string;
  artists?: Array<{ id?: number | string; name: string }>;
  album?: { id?: number | string; name: string };
  songId?: number | string;
  coverUrl?: string;
}

export const applyMatchedMetadata = async (
  songId: string,
  metadata: MatchedLocalMetadata,
  options: {
    lyricsOnly?: boolean;
    songPatch?: Partial<LocalSong>;
    protectOrigins?: LocalLibraryAssignmentOrigin[];
    assignmentOrigin?: Extract<LocalLibraryAssignmentOrigin, 'auto-match' | 'manual-match'>;
    /** 自动匹配写回用：库里这首已被用户标记为纯音乐（匹配途中刚标上的也算）时整次不写，原样返回。 */
    skipIfMarkedPureMusic?: boolean;
  } = {},
): Promise<LocalSong | undefined> => {
  const result = await appDatabase.transaction(
    'rw',
    [appDatabase.local_music, appDatabase.local_library_entities, appDatabase.local_library_assignments],
    async () => {
      const song = await appDatabase.local_music.get(songId);
      if (!song) return undefined;
      if (options.skipIfMarkedPureMusic && song.markedPureMusic) return song;
      const updatedSong: LocalSong = { ...song, ...options.songPatch };
      const assignmentOrigin = options.assignmentOrigin || 'auto-match';
      if (metadata.source) {
        updatedSong.onlineMetadata = {
          source: metadata.source,
          songId: metadata.songId,
          albumId: metadata.album?.id,
          title: cleanLocalLibraryName(metadata.title),
          artists: metadata.artists?.filter(artist => cleanLocalLibraryName(artist.name)) || [],
          album: cleanLocalLibraryName(metadata.album?.name)
            ? { id: metadata.album?.id, name: cleanLocalLibraryName(metadata.album?.name)! }
            : undefined,
          coverUrl: metadata.coverUrl,
          matchMode: assignmentOrigin === 'manual-match' ? 'manual' : 'auto',
          matchedAt: Date.now(),
        };
      }
      if (!options.lyricsOnly) {
        const entities = await appDatabase.local_library_entities.toArray();
        const current = await appDatabase.local_library_assignments.get(songId);
        const protectedOrigins = new Set(options.protectOrigins || []);
        const hasArtistMetadata = metadata.artists !== undefined
          && !Boolean(current && protectedOrigins.has(current.artistOrigin));
        const artists = metadata.artists?.filter(artist => cleanLocalLibraryName(artist.name)) || [];
        const artistIds = hasArtistMetadata
          ? resolveEntityNames(entities, 'artist', artists.map(artist => artist.name), current?.artistEntityIds)
          : current?.artistEntityIds || [];
        const hasAlbumMetadata = Boolean(cleanLocalLibraryName(metadata.album?.name))
          && !Boolean(current && protectedOrigins.has(current.albumOrigin));
        const albumName = hasAlbumMetadata ? cleanLocalLibraryName(metadata.album?.name) : undefined;
        const albumId = albumName
          ? resolveEntityNames(entities, 'album', [albumName], current?.albumEntityId ? [current.albumEntityId] : [])[0]
          : current?.albumEntityId;
        if (metadata.title?.trim()) {
          updatedSong.title = metadata.title.trim();
          updatedSong.titleOrigin = assignmentOrigin;
        }
        await Promise.all([
          appDatabase.local_library_entities.bulkPut(entities),
          appDatabase.local_library_assignments.put({
            songId,
            artistEntityIds: artistIds,
            artistOrigin: hasArtistMetadata ? assignmentOrigin : current?.artistOrigin || 'import',
            albumEntityId: albumId,
            albumOrigin: hasAlbumMetadata ? assignmentOrigin : current?.albumOrigin || 'import',
            updatedAt: Date.now(),
          }),
        ]);
      }
      const sanitized = sanitizeLocalSongForStorage(updatedSong);
      await appDatabase.local_music.put(sanitized);
      return sanitized;
    },
  );
  if (result) {
    if (result.matchedLyrics) {
      void writeOfflineSavedLyricsForSong(result.id, result.fileSignature, result.matchedLyrics);
    }
    void updatePersistedLibraryIndexSongs([result]);
  }
  return result;
};

export const applyManualMetadata = async (
  songId: string,
  artistNames: string[],
  albumName?: string,
): Promise<LocalSong | undefined> => {
  return await appDatabase.transaction(
    'rw',
    [appDatabase.local_music, appDatabase.local_library_entities, appDatabase.local_library_assignments],
    async () => {
      const song = await appDatabase.local_music.get(songId);
      if (!song) return undefined;
      const entities = await appDatabase.local_library_entities.toArray();
      const current = await appDatabase.local_library_assignments.get(songId);
      const cleanedArtists = artistNames.flatMap(splitLocalLibraryArtistNames);
      const cleanedAlbum = cleanLocalLibraryName(albumName);
      const artistIds = resolveEntityNames(entities, 'artist', cleanedArtists, current?.artistEntityIds);
      const albumId = cleanedAlbum
        ? resolveEntityNames(entities, 'album', [cleanedAlbum], current?.albumEntityId ? [current.albumEntityId] : [])[0]
        : undefined;
      await Promise.all([
        appDatabase.local_library_entities.bulkPut(entities),
        appDatabase.local_library_assignments.put(createLocalLibraryAssignment(songId, artistIds, albumId, 'manual')),
      ]);
      return song;
    },
  );
};

export const restoreImportedMetadata = async (
  songId: string,
  songPatch: Partial<LocalSong> = {},
): Promise<LocalSong | undefined> => {
  const result = await appDatabase.transaction(
    'rw',
    [appDatabase.local_music, appDatabase.local_library_entities, appDatabase.local_library_assignments],
    async () => {
      const song = await appDatabase.local_music.get(songId);
      if (!song) return undefined;
      const restored: LocalSong = {
        ...song,
        ...songPatch,
        title: song.importedMetadata.title,
        titleOrigin: 'import',
      };
      const entities = await appDatabase.local_library_entities.toArray();
      const current = await appDatabase.local_library_assignments.get(songId);
      const artistEntityIds = resolveEntityNames(
        entities,
        'artist',
        getImportedArtistNames(restored),
        current?.artistEntityIds,
      );
      const albumName = getImportedAlbumName(restored);
      const albumEntityId = albumName
        ? resolveEntityNames(entities, 'album', [albumName], current?.albumEntityId ? [current.albumEntityId] : [])[0]
        : undefined;
      const sanitized = sanitizeLocalSongForStorage(restored);
      await Promise.all([
        appDatabase.local_music.put(sanitized),
        appDatabase.local_library_entities.bulkPut(entities),
        appDatabase.local_library_assignments.put(createLocalLibraryAssignment(
          songId,
          artistEntityIds,
          albumEntityId,
          'import',
        )),
      ]);
      return sanitized;
    },
  );
  if (result) {
    if (result.matchedLyrics) {
      void writeOfflineSavedLyricsForSong(result.id, result.fileSignature, result.matchedLyrics);
    }
    void updatePersistedLibraryIndexSongs([result]);
  }
  return result;
};

const getAssignmentEntityIds = (assignment: LocalLibraryAssignment): string[] => [
  ...assignment.artistEntityIds,
  ...(assignment.albumEntityId ? [assignment.albumEntityId] : []),
];

const collectOrphanedEntityIds = (
  deletedAssignments: LocalLibraryAssignment[],
  remainingAssignments: LocalLibraryAssignment[],
  entities: LocalLibraryEntity[],
): string[] => {
  const { entitiesById } = buildLocalLibraryIndex(entities);
  const resolveEntityId = (entityId: string) => followEntityRedirect(entityId, entitiesById) || entityId;
  const affectedEntityIds = new Set(
    deletedAssignments.flatMap(getAssignmentEntityIds).map(resolveEntityId),
  );
  const referencedEntityIds = new Set(
    remainingAssignments.flatMap(getAssignmentEntityIds).map(resolveEntityId),
  );

  return entities
    .filter(entity => {
      const resolvedId = resolveEntityId(entity.id);
      return affectedEntityIds.has(resolvedId) && !referencedEntityIds.has(resolvedId);
    })
    .map(entity => entity.id);
};

// Deletes songs and assignments atomically, then removes only entity families with no remaining members.
const deleteSongRecords = async (songIds: string[]): Promise<void> => {
  const uniqueSongIds = Array.from(new Set(songIds));
  if (uniqueSongIds.length === 0) return;
  let deletedCoverAssetIds: string[] = [];

  await appDatabase.transaction(
    'rw',
    [
      appDatabase.local_music,
      appDatabase.local_library_entities,
      appDatabase.local_library_assignments,
    ],
    async () => {
      const deletedSongIdSet = new Set(uniqueSongIds);
      const [deletedSongs, deletedAssignments, assignments, entities] = await Promise.all([
        appDatabase.local_music.bulkGet(uniqueSongIds),
        appDatabase.local_library_assignments.bulkGet(uniqueSongIds),
        appDatabase.local_library_assignments.toArray(),
        appDatabase.local_library_entities.toArray(),
      ]);
      const orphanedEntityIds = collectOrphanedEntityIds(
        deletedAssignments.filter((assignment): assignment is LocalLibraryAssignment => Boolean(assignment)),
        assignments.filter(assignment => !deletedSongIdSet.has(assignment.songId)),
        entities,
      );
      deletedCoverAssetIds = deletedSongs.flatMap(song => song?.localCoverAssetId ? [song.localCoverAssetId] : []);

      await Promise.all([
        appDatabase.local_music.bulkDelete(uniqueSongIds),
        appDatabase.local_library_assignments.bulkDelete(uniqueSongIds),
        appDatabase.local_library_entities.bulkDelete(orphanedEntityIds),
      ]);
    },
  );
  await deleteUnreferencedLocalCoverAssets(deletedCoverAssetIds);
};

export const deleteSongAssignment = async (songId: string): Promise<void> => deleteSongRecords([songId]);

export const deleteSongAssignments = async (songIds: string[]): Promise<void> => deleteSongRecords(songIds);

